window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_069"]={"n":"李昌祺","dyn":"明","poems":[{"t":"过吴门次萨天锡韵","f":"七言古诗","c":["七泽三江通甫里，杨柳芙蓉照湖水。","阊门过去是盘门，半掩珠帘画楼里。","靡芜生遍鸳鸯沙，东风落尽棠梨花。","馆娃香径走麋鹿，清夜鬼灯明绛纱。","三高祠下东流续，真娘墓上风吹竹。","西施去后屧廊倾，岁岁春深烧痕绿。"]},{"t":"送陈郎中重使西域十首 其七","f":"五言律诗","c":["宝带悬鱼服，雕弧挂马鞯。","皇恩覃万国，虏气静三边。","瀚海寒生月，崖城暮锁烟。","欲穷西域事，班范有遗编。"]},{"t":"送陈郎中重使西域十首 其九","f":"五言律诗","c":["出塞春乘传，投鞭晚下营。","旋风胡马疾，掣电皂雕轻。","浩荡穷源志，迢遥奉使程。","支机如得石，持往问君平。"]},{"t":"送陈郎中重使西域十首 其十","f":"五言律诗","c":["行尽伊吾道，胡天气候殊。","神僧留白骨，毒草隐玄蛛。","近水多行帐，穷荒绝远书。","伫看归觐日，玉勒控宛驹。"]},{"t":"宿端壁寺","f":"五言律诗","c":["遗构象王宫，荒凉小邑东。","一灯秋殿闭，孤榻夜窗空。","饥啮床头鼠，愁吟砌下蛩。","萧萧黄叶坠，庭树颤西风。"]},{"t":"彭泽县石崖僧房","f":"五言律诗","c":["窗户俯澄潭，龙宫似可探。","藤萝栖鹘树，瓶锡定僧岩。","斜日疏疏磬，长风去去帆。","只应输野衲，长此卧烟岚。"]},{"t":"早发小孤山遇风","f":"五言律诗","c":["湖尽江逾阔，舟行路若迷。","垂杨春寂寂，芳草雨凄凄。","漩水鼋鼍窟，平沙雁鹜堤。","风波随地有，何处可幽栖。"]},{"t":"次襄城","f":"五言律诗","c":["晨铎语西风，衣单怯露浓。","豆苗遮地黑，柿实照园红。","晓色苍茫里，秋光惨淡中。","永怀东汉士，风裁李膺雄。"]},{"t":"送人南归四首 其一","f":"五言律诗","c":["离弦兼楚调，忍向醉时闻。","连岁长为客，他乡更别君。","鸥波明夕照，雁字写秋云。","迢递还乡梦，相随过海门。"]},{"t":"送人南归四首 其四","f":"五言律诗","c":["年年长在客，北蓟复南京。","秋雨沧洲雁，春风采石莺。","好山环故里，流水背孤城。","去住无拘系，閒身到处轻。"]},{"t":"喜张进士叔豫见宿旅舍","f":"五言律诗","c":["穷巷寂无邻，青灯共故人。","远声霜下磬，孤影客边身。","露冷蛩相吊，庭寒月自亲。","殷勤一瓢酒，更与话酸辛。"]},{"t":"周原幽居","f":"五言律诗","c":["山色蛾眉秀，江流燕尾分。","乱蝉吟落日，独鹤引归云。","黄叶溪边树，青帘雨外村。","兴来留客坐，随意倒芳樽。"]},{"t":"送陈生归吉水赤岸二首 其一","f":"五言律诗","c":["清砧兼落叶，总是别离情。","去路千程远，归舟一叶轻。","秋云连树暗，寒日映川明。","亦有沧浪兴，何时共濯缨。"]},{"t":"送周秀才游长沙","f":"五言律诗","c":["迢递长沙道，萧条晏岁游。","乱山黄叶寺，孤棹白蘋洲。","夕鸟冲船过，寒波背郭流。","毋论卑湿地，贾傅昔曾留。"]},{"t":"送戴教授北行","f":"五言律诗","c":["别路三春雨，行舟五两风。","花香随路减，柳色上衣浓。","共是青云客，先成白发翁。","离情如逝水，万折亦朝东。"]},{"t":"宿废普济寺","f":"五言律诗","c":["青山行欲尽，深树见僧房。","云气千峰暝，秋声一院凉。","长藤悬破衲，脱叶覆空廊。","龙象黄金地，萧萧蔓草长。"]},{"t":"拟唐塞下曲九首 其三","f":"五言律诗","c":["铁骑蹴交河，衔枚半夜过。","雪花凝锁甲，月色冷雕戈。","黠虏俱亡命，连营尽凯歌。","至今青冢骨，犹恨与通和。"]},{"t":"三月四日即景","f":"五言律诗","c":["忽忽春将暮，俄过三月三。","草谁怜益母，花自媚宜男。","乍到寻巢燕，初眠上箔蚕。","新茶与新笋，乡味忆江南。"]},{"t":"赋落花","f":"七言律诗","c":["愁红怨粉各依依，树下偏多树上稀。","总为春光争艳冶，却教夜雨妒芳菲。","数枝浸水鱼吹去，几片萦林蝶趁飞。","莫怪东风成薄倖，犹能收拾点人衣。"]},{"t":"酬曾学士子棨见赠复职之作","f":"七言律诗","c":["放逐仍居患难中，三年执役梵王宫。","病来短发逢秋白，老去衰颜借酒红。","心似葵花倾晓日，身同树叶感霜风。","杜陵花竹频生梦，但觉阳春处处融。"]},{"t":"张舒州家观元承旨危素画像","f":"七言律诗","c":["虞揭凋零玉署空，堂堂至正独推公。","气全河岳英灵秀，手抉云霞制作工。","江总归陈翻恨老，贾生鸣汉早称雄。","丹青似有无穷意，却写南冠入画中。"]},{"t":"柳","f":"七言律诗","c":["含烟袅雾自青青，爱近官桥与驿亭。","春满章台偏婀娜，秋深隋岸最凋零。","长从苏小门前折，几向龟年笛里听。","绝胜东风桃李树，飞花犹解化浮萍。"]},{"t":"驾幸朝天宫祭星之作","f":"七言律诗","c":["上帝萧台卫百灵，储皇拂曙醮群星。","清都秘箓开云篆，白昼神雷掷火铃。","晓露未乾珠树湿，天风微动宝花零。","叨恩久在南宫里，长从銮舆幸冶亭。"]},{"t":"孝陵秋日陪祀柬彭赞礼永年","f":"七言律诗","c":["钟山欲晓色苍苍，小辇轻舆出建章。","苑鹿不惊仙仗过，潭龙故喷御泉香。","重城隐雾留残月，高树含风送早凉。","惟有祠官最清贵，时来导驾沐恩光。"]},{"t":"送熊生还乡","f":"七言律诗","c":["石头城下柳萧疏，久客怀归念远途。","乡梦每生钟断后，客愁政在酒醒初。","扁舟暮雨青衫薄，折苇凉风白鸟孤。","拟共丘园寻别业，临岐相送独踟蹰。"]},{"t":"晚春郊外七首 其二","f":"七言律诗","c":["柳外轻风拂面来，春忙半是杜鹃催。","多般野菜参差老，几样林花接续开。","竹为近阶难迸笋，松因临水易生苔。","追思往日嬉游伴，聚散如云倍可哀。"]},{"t":"晚春郊外七首 其六","f":"七言律诗","c":["雨外林鸠不住啼，落红狼籍半沾泥。","秧苗带谷根犹浅，麦干垂花穗已齐。","鸥下只投荷叶屿，蝶飞多傍菜花畦。","青山绿水饶诗景，归路扶筇醉懒题。"]},{"t":"杨柳枝 其二","f":"七言绝句","c":["参差几树瞰长河，树树垂金拂绿波。","不是秋来易零落，自缘人世别离多。"]},{"t":"杨柳枝 其三","f":"七言绝句","c":["细叶如眉绿未匀，修眉浑似带愁颦。","输他桃杏东风里，不管南游北去人。"]},{"t":"客夜闻砧","f":"七言绝句","c":["荒草萧萧郭隗台，清砧明月两堪哀。","千愁百感多如雨，今夜灯前一并来。"]},{"t":"房山旅舍","f":"七言绝句","c":["枕寒衾冷对孤灯，室似邮亭榻似僧。","清泪几行揩又落，斜风细雨送残更。"]},{"t":"重游龙济寺悼无为能上人","f":"七言绝句","c":["北涉南游二十霜，幻身重到赞公房。","苔侵素壁松枝偃，独自焚香拜影堂。"]},{"t":"新安谣三首 其一","f":"七言绝句","c":["新安野老发垂肩，说著先朝泪泫然。","洪武初年真少事，几曾轻到县衙前。"]},{"t":"新安谣三首 其二","f":"七言绝句","c":["垂老频逢岁薄收，秋租多欠卖耕牛。","县官不暇怜饥馁，唤拽官车上陕州。"]},{"t":"新安谣三首 其三","f":"七言绝句","c":["当夫当匠子孙亡，田地荒芜户有粮。","昨日迤西蕃使过，尽驱妇女赶牛羊。"]},{"t":"山路谑花","f":"七言绝句","c":["枝头地上总猩红，几树繁开几树空。","颜色一般荣悴异，谁将此意问东风。"]},{"t":"山中见牡丹","f":"七言绝句","c":["不嫌恶雨并乖风，且共山花作伴红。","纵在五侯池馆里，可能春去不成空。"]},{"t":"重唁山中牡丹","f":"七言绝句","c":["不烦浇灌不烦栽，长过清明谷雨开。","为问洛阳豪贵客，几家还有旧亭台。"]},{"t":"宜阳山中","f":"七言绝句","c":["绿阴重叠鸟间关，野枣花香宿雨残。","天遣浮云都捲尽，教人一路看青山。"]},{"t":"嵩县过端午","f":"七言绝句","c":["老大偏多故里心，一逢佳节一沾襟。","谁知此日菖蒲酒，又在山城独自斟。"]},{"t":"栀子画眉图二首 其一","f":"七言绝句","c":["薝卜初开雪亚枝，枝头好鸟立成痴。","少年京兆风流处，似汝花间对语时。"]},{"t":"栀子画眉图二首 其二","f":"七言绝句","c":["昔年曾伴董娇娆，长把春山笑倩描。","今日梁园空见画，鸟啼花落鬓萧萧。"]},{"t":"乡人至夜话","f":"七言绝句","c":["形容不识识乡音，挑尽寒灯到夜深。","故旧凭君休更说，老怀容易便沾襟。"]},{"t":"秋雨夜闻乡中近事殊可感","f":"七言绝句","c":["得失无心总不惊，秋来偏动故乡情。","寻常窗外梧桐雨，不似今宵不耐听。"]},{"t":"至正妓人行","f":"七言古诗","c":["桃花含露伤春老，莲叶欺霜悴秋早。","红飘翠殒谁可方？","大都伎人白头媪。","言辞婉媚虽足爱，颜色萎摧宁再好？","姿同蒲柳先凋零，景近桑榆渐枯槁。","我役房山滞客边，客边意气迥非前。","螺杯谩想红楼饮，雁柱徒怀锦瑟弦。","晏岁荒村因解后，芳尊小酌且留连。","阳台楚雨情磨灭，舞袖弓鞋事弃捐。","于今沦落依草木，天寒幽居在空谷。","爷娘底处认坟墓，姊妹何乡寻骨肉。","初谓终身永欢笑，那知末路翻捞摝。","莫惜缥囊紫玉箫，暂吹绛阙瑶台曲。","停觞起立态是痴，敛衽踌躇半饷时。","凝情徘徊倾听久，微茫杳渺度腔迟。","娇痴睍睆莺求友，嫩讶呢喃燕哺儿。","巨壑潜蛟惊起蛰，危巢别鹄苦分离。","分离或变成凄切，凄切愈加音愈咽。","荡子江湖信息稀，疲兵关塞肌肤裂。","似啼似诉复似泣，若慕若怨兼若诀。","孤舟嫠妇旅魂消，异域累臣鬓毛折。","参差角羽杂宫商，微韵纡馀巧抑扬。","坠絮游丝争绕乱，哀蛩怨蚓互低昂。","呦呦瑞鹿剔灵囿，哕哕和鸾集建章。","楚弄数声谐洗簇，氐州一曲换伊凉。","伊凉溜亮益闲暇，埙篪笛笙皆在下。","琚瑀铿锵韵碧霄，机梭淅沥鸣玄夜。","须臾众调多周遍，返席重论盛年话。","一自干戈据扰攘，几多行辈遄沦谢。","记得先朝至正初，奴家才学上头颅。","银环约臂联条脱，彩线采绒缀罛罟。","博局倦馀邀伴赌，秋千蹴罢倩人扶。","纤腰数被邻姬妒，鬓发常烦阿姐梳。","羽林英俊驰轻縠，惯向奴家通夕宿。","凤枕鸾衾肯暂辜，蜂媒蝶使交相属。","冰客反惧胭粉涴，香体匪藉沉檀浴。","退居始替兴圣斑，内使传宣又催促。","宇宙雍熙百姓安，仁覃四裔覆三韩。","畏吾选作必阇赤，钦察恩深答刺罕。","已见拂郎呈崿袅，还闻缅甸贡琅玕。","丹楹陡峻栖蘖鹊，华表玲珑镂角端。","神州形胜真佳丽，郁郁葱葱蟠王气。","五谷丰登免税粮，九重娱乐耽声妓。","广寒宵得侍乞巧，太液晨许陪修禊。","避暑巡游欲届程，沿途宿顿争除地。","随銮供奉拣娉婷，特敕奴家扈跸行。","卤簿晓排仙仗发，抹伦晴鞠绣鞍乘。","营间鼓镯轰雷动，碛外氛埃扫电清。","纨扇试时违大内，花园过去是开平。","宗王贵戚咸来会，崧呼万岁齐齐跪。","绯缨帽妥钵焦圆，黑瓣髻纫卜郎锐。","后先雉扇怯薛执，左右麟符火赤佩。","茜罽缝袍竺国师，霞绡蹙帔天魔队。","齐姜宋女总寻常，惟诧奴家压教坊。","乐府竞歌新北令，构栏慵做旧《西厢》。","煞寅院本编蒙赏，喝采箜篌每擅场。","浑脱囊盛阿剌酒，达拿珠络只徐裳。","胡元运祚俄然歇，远遁龙荒弃城阙。","官里遥冲朔漠尘，哈敦暗哭穹庐月。","坏宫昼静著封锁，虚室苔生罢朝谒。","绝徼阴森部落衰，中原澒洞烽烟热。","填沟塞堑总婵娟，蚁虱微躯幸瓦全。","窈窕蛾眉浑懒画，蹒跚茧足亦羞缠。","祇园披剃思依佛，梵榻跏趺儗学禅。","练衲正宜参般若，赤绳无奈堕痴缘。","兰心慧性非坚固，宛转绸缪媒妁误。","嫁与凡庸里巷儿，流为鄙贱糟糠妇。","文禽失类偶鸡鹜，孔雀迷群随鹘鹭。","手具盘飧奉舅姑，亲操井硙应门户。","物换星移十载强，尊嫜殂没藁砧亡。","屡遭疾疫男捐馆，苦迫饥寒媳去房。","瓦缶泥垆长是伴，瑶簪翠钿已相忘。","忍谈富贵徒增感，怕说酸辛只断肠。","筋骸疲惫龙钟久，里舍么娘嗤老丑。","涂抹伊谁识阿婆，弹搊竞自矜纤手。","偷生又幸逢明代，垂死宁当正丘首。","轗轲颓龄谅弗多，槎牙瘦骨行将朽。","欷歔叹古更嗟今，少日荣华晚陆沉。","亹亹愿毋嫌䀨耳，寥寥罕遇是知音。","织乌荏苒忙过隙，司马汍澜已湿衿。","往运推移端莫挽，穷途汨没最难禁。","妓人听我相宽慰，美貌多为姿质累。","仓惶明镜乐昌分，缥缈层楼绿珠坠。","虽云茕独困贫乏，嬴得娇娆到憔悴。","世上浮名不直钱，杯中醇酎休辞醉。","屏营抆泪起逶迤，载拜殷勤乞赋诗。","土炕蓬窗愁寂夜，挑灯快读解愁颐。","那知皓首逢元稹，弗用黄金铸牧之。","洒翰酬渠增慷慨，风流千载系遐思。"]},{"t":"柳梢青 题秋塘图","f":"古风","c":["落尽芙蓉，收残菱芡，晚色凄迷。","断荇随流，枯荷折柄，秋满苏堤。","沙禽自在幽栖。","极浦外、天连水低。","粉坠莲房，波漂菰米，烟暝湖西。"]},{"t":"拟影赠形","f":"五言古诗","c":["太极生万汇，繄人最为灵。","云胡浪自苦，驰骛迹靡宁。","化机有恒运，疾急弗暂停。","适见方红颜，鬓发忽已星。","人身非金石，终当归沉冥。","不如学神仙，服食炼尔形。","君我两无坏，永共天地龄。","愿君取吾语，日进参与苓。"]},{"t":"形答影","f":"五言古诗","c":["有形斯有影，物理固其常。","我行尔必偕，我息尔乃藏。","岂但相依附，实此同存亡。","学仙非无术，却老亦有方。","古称彭聃辈，其寿邈难量。","于今竟安在，孰是长生乡。","多君为余劝，兹道终杳茫。","参苓且当止，莫若衔杯觞。"]},{"t":"神释","f":"五言古诗","c":["人生斯世间，于物亦岂殊。","二仪妙参赞，政由我中居。","与子虽三名，其实本一躯。","出处既弗异，如何乖所趋。","老氏贵不死，长生出贪愚。","神仙果何物，天地尚或渝。","饮酒固所好，悲愁赖其驱。","从古戒沈湎，先王有遗书。","学仙非吾事，痛饮岂我图。","但当委大运，俟命宁忧虞。","既来谅必去，此理端不诬。","逍遥以乘化，荷锸徒区区。"]},{"t":"甲戌九日陪泷冈先生暨诸友登高旌阳宫分韵得影字","f":"五言古诗","c":["蛩鸣霜清候，叶飞秋尽景。","萸菊方交秀，琴册亦暂屏。","逡巡出芹泮，次第陟松岭。","涉隘齿或乱，升旷序还整。","登降屡断续，赓酬互驰骋。","柽林递阴森，藓径极修永。","席地藉山云，临流漱石井。","欲投岩栖人，拂衣世外境。","寄情园兼绮，洗心箕与颍。","缝掖既身被，逸致只神领。","偶此谐一醉，已见夕月影。"]},{"t":"渊明酌酒图","f":"五言古诗","c":["耕耨有馀暇，荫此榆柳阴。","燕坐对佳菊，解襟独长吟。","老农得美酒，负榼远见寻。","呼儿涤尘爵，相与聊共斟。","终觞兀然醉，富贵非所钦。","吾生讵能几，为乐当自今。"]},{"t":"洞章一首送彭道士","f":"五言古诗","c":["赤明肇无始，玉京耸神霄。","真人遏死路，五老御灵飙。","玄梵超溟涬，豁落开幽寥。","中有浩劫尊，绛节诸天朝。","丹光耀明景，春华凌翠条。","欲结无穷游，飞神蹑璇杓。","稽首拜太上，高举同逍遥。"]},{"t":"题松菊堂卷","f":"五言古诗","c":["久矣厌流俗，稍与世背驰。","癖性爱松菊，并植当轩墀。","幽居无他玩，雅好良在兹。","清风忽然至，天籁鸣参差。","凉露晓厌浥，众蕊含华滋。","顾渠岁寒物，自与静者宜。","不形丁生梦，聊咏陶翁诗。","养拙茅檐下，过此非所期。"]},{"t":"松石间意轩","f":"五言古诗","c":["夙有山水癖，已忘天路游。","屏迹衡门下，爱此松石幽。","青松荫我屋，白石临溪流。","逍遥曳藜杖，抚玩舒烦忧。","老农解吾意，负榼远见投。","忻然笑相命，且共饮数瓯。","倦即憩石坐，时还抚松讴。","尽此一日乐，明日非吾谋。","醉眠松下石，孰谓此生浮。"]},{"t":"送友人故乡访族","f":"五言古诗","c":["秋雨浃旬月，积潦连平津。","慨然理舟楫，访我族中人。","相去实缅邈，悠悠隔冬春。","同源既分流，万世本一身。","驾言远相唁，讵敢辞艰勤。","丘垄得洒扫，尊酌且复亲。","虽未获久处，暂来亦所欣。","感此迟莫年，再至恐无因。","各愿爱体素，令德期日新。"]},{"t":"题晚香堂二首 其一","f":"五言古诗","c":["弱志弗苟尚，遂与世好殊。","性本爱闲逸，种菊绕蓬庐。","时当雪霜厉，群卉悴无馀。","斯花独敷荣，为我莫景娱。","掇英泛美酒，燕坐当前除。","菊可制颓龄，酒能解饥劬。","陶然有真乐，此外奚所需。","俯仰天地间，百年复何如。","寄语达生者，浮名岂能拘。"]},{"t":"题晚香堂二首 其二","f":"五言古诗","c":["靡靡秋日晏，凄凄霜露零。","纷纷众卉悴，粲粲佳菊荣。","我实幽居士，适此隐遁情。","园林无来躅，窗户有馀清。","床前一壶酒，满泛黄金英。","长歌散襟颜，歌竟时自倾。","颓然既就醉，此乐将不胜。","微愿良易足，多技岂吾营。","余生后彭泽，千载仰德馨。"]},{"t":"送何教授奉母还临川且省其父","f":"五言古诗","c":["秋日凄以白，游子念归还。","奉母载官舫，驾言还临川。","王门岂不乐，所惜慈侍偏。","况兹严亲在，家居垂莫年。","温凉谨问候，子职愧久愆。","今我幸具庆，而可各一天。","故山有高堂，二老心所便。","岂无一觞酒，跪劝当几前。","敢谓美昼绣，庶用怡华颠。","依依恋膝下，眷眷怀日边。","重来勉尽瘁，移孝乃为贤。"]},{"t":"乘化室","f":"五言古诗","c":["素发被秋鬓，筋力与昔殊。","人身非金石，岁月苦易徂。","麟原有青山，真宅预可图。","穿云斲隧穴，密甃圆且虚。","石兽既外列，瓦棺亦中储。","前立两翁仲，傍蹲一龟趺。","地灵暨木伯，呵护卫以驱。","四序自更迭，大运诚须臾。","千秋百岁后，瞑目归斯庐。","油然委蜕去，此外复何虞。"]},{"t":"题爱日堂","f":"五言古诗","c":["逝景如奔流，昼夜东向驰。","岁月谅难尽，人生信有涯。","所以孝子心，惄焉抱深悲。","举头视慈颜，已觉非昔时。","适见双鬓玄，于今成素丝。","念之益增感，何由报恩私。","晨兴启高堂，甘旨具在兹。","奉觞祝亲寿，愿共春晖迟。","以斯菽水欢，为彼衰莫怡。","去日莫能挽，遐算或可期。","庶几崦嵫照，不异扶桑曦。"]},{"t":"题山水小景","f":"五言古诗","c":["野外少人躅，值此佳日迟。","偶与二三友，游观赋新诗。","青松蔼繁荫，碧草含华滋。","逍遥恣言笑，童稚亦娱嬉。","济济炫春服，悠悠咏清沂。","兹欢恐难再，兴尽以为期。"]},{"t":"题湖山佳趣卷","f":"五言古诗","c":["宦游惬深好，乃在名胜区。","山水自足适，况兹职文儒。","横经有馀闲，逍遥出通衢。","春服各已成，遂与童冠俱。","徘徊恣言笑，登陟忘饥劬。","晴鸢戾层空，弱藻翻文鱼。","至理与景会，天机独吾娱。","悠悠仰川上，眷眷怀舞雩。","咏歌返黉舍，高兴谁能谕。"]},{"t":"梁处士挽诗一首","f":"五言古诗","c":["凉飙振庭树，殒星当前除。","伊人此遐逝，敛衽归玄庐。","翩翩丹旐扬，祖行在须臾。","衣冠閟重泉，体魄寄荒墟。","浮生虽有尽，令德谅不渝。","没世苟无述，百年复何如。","梁鸿凛遗烈，千载与之俱。"]},{"t":"容膝轩","f":"五言古诗","c":["一室廑如斗，堆床置琴书。","耕读得闲暇，危坐心自娱。","天光在瓮牖，席门挂绳枢。","已忘朝市荣，聊依野人居。","环堵本隘陋，于我信有馀。","陶然俯仰间，八荒在庭除。","岂但一榻外，六合真吾庐。","即此自宽裕，广厦空渠渠。"]},{"t":"春日与高逸人行秦淮河上作","f":"五言古诗","c":["端居苦无悰，今旦得良契。","逍遥出近郭，散策淮水际。","草软倦堪眠，林香醉宜憩。","鸟哢晴始和，川容晚逾媚。","筱深风苇密，沙没夕潮至。","野鹭浑忘机，似识静者意。","幽怀颇得惬，逝景苦难系。","候卒晡欲还，春城暝将闭。","因知市朝隐，兼有林壑致。","永言终此生，涵泳太平世。"]},{"t":"金溪邓处士挽诗","f":"五言古诗","c":["永夕少微坠，伊人亦长捐。","萧条薤露歌，祖行出荒阡。","遗骸寄空木，逝魄归穷泉。","有生谅必死，自古莫不然。","矧兹得高寿，况乃归其全。","瞑目可无憾，苟生真足怜。","鄙哉学仙子，服食希遐年。"]},{"t":"具庆堂","f":"五言古诗","c":["高门多积庆，父母喜俱完。","兄弟亦无故，妻子复团栾。","况兹值明时，怀绂为县官。","民淳众务简，日夕闲且安。","命妇出中房，具彼餐与盘。","怡然一室内，骨肉恒相看。","至养在承顺，菽水有馀欢。","简书谅足畏，忧患何能干。"]},{"t":"徐道士安处轩","f":"五言古诗","c":["尘氛既屏绝，气宇亦澄鲜。","心恬境逾寂，虑遣情自捐。","结宇依层岩，开轩俯重渊。","遥林含宿雨，古树带秋烟。","落花晚成积，归鸟夕知还。","习静泯众累，守默息万缘。","清虚固其性，声利岂所便。","智黜道乃得，朴返真斯全。","将随凤鸾侣，以引龟鹤年。"]},{"t":"渊明图","f":"五言古诗","c":["閒居寡人事，逍遥步里中。","风霜凋众卉，独荣见孤松。","南山忽在眼，佳菊亦成丛。","欣然纵游眺，况兹年岁丰。","幸有盈瓶酒，酬劝偕老农。","醉来多奇趣，岂必丝与桐。"]},{"t":"冶城怀古","f":"五言古诗","c":["趍朝退北阙，吊古来西州。","忠贞结缨处，松柏馀荒丘。","萧条伯气歇，惨澹寒云浮。","嗟哉晋多士，孰奋匡君谋。","壸也真丈夫，毅然无匹俦。","父子著伟烈，奸谀詟芳猷。","英姿俨遗祠，信史芬馀休。","疏钟冶城晚，落木秦淮秋。","我来事蒐访，往迹犹可求。","如何忠孝名，不在旷达流。","诚知清谈高，宁执鄙吝优。","同朝江左贤，颡泚徒怀羞。","徘徊凝望久，日落长烟收。"]},{"t":"题亡羊图","f":"五言古诗","c":["澹无组绂累，夙志爱林泉。","挟册驱羝群，箕踞丛筱边。","玩绎造芒芴，超遥谢蹄筌。","微风延众籁，落日明长川。","心景适相契，物我遽两捐。","尔羊本非□，我书亦空诠。","不写谷生博，画师无乃偏。","执业虽各途，亡羊奚异旃。","固知东陵愚，岂及西山贤。","徇名与徇利，均死何后先。","弃置且勿较，呼儿进杯棬。"]},{"t":"哀萧教授引之","f":"五言古诗","c":["衔哀读铭诔，悲泪若河悬。","念我同门友，于今在九泉。","契阔虽云远，情好乃逾坚。","都门送别时，何意遽长捐。","达宦每在晚，朝露竟溘先。","一夕成长往，二胤仍各天。","枯骼委烈焰，馀烬藏墓田。","人生孰无死，礼葬固所贤。","等为归腐朽，终当随化迁。","所以旷达士，形骸岂复怜。","佳名苟不没，讵必分乌鸢。"]},{"t":"题王司直所藏米南宫画","f":"五言古诗","c":["幽壑霁残雨，飞云昼濛濛。","大江泻练遥，上与银汉通。","村墟极平圹，岛屿迷西东。","长林隐空舍，众籁吟天风。","悬崖忽焉断，浩荡烟涛雄。","夕岚落霞外，把钓何老翁。","流水共情性，沙鸟知心胸。","浩然沧浪歌，濯足清潭中。","始知簪绂华，不与渔樵同。","兴适随去留，身閒忘达穷。","我生本放浪，中年抗尘容。","观图思初服，脱屣期息躬。","长揖凤鸾侣，永投鸥鹭踪。","自此卸衔勒，郊原春草丰。"]},{"t":"题十八学士图","f":"五言古诗","c":["慨观瀛洲画，经济怀群公。","唐宫委蔓草，寂寞昭陵空。","天策旧多士，犹馀图卷中。","乘时翊昌运，磊落皆豪雄。","论思过丙夜，鱼水欣遭逢。","辉光惊时人，文翰动九重。","粉绘劳相臣，褒词烦褚翁。","白云鹤笙远，即此真方蓬。","勋业岂弗高，声华亦云崇。","终然太平治，所愧乃国风。","谋谟匪无材，王佐自不同。","邈哉夔契辈，谁能写其容。"]},{"t":"独酌有述","f":"五言古诗","c":["沉忧如积痾，纡郁剧焚燎。","深在膏肓间，异镜谅难照。","往圣垂方书，万病皆有疗。","独兹莫措手，浑沌无朕兆。","尝闻达人言，扫涤酒其要。","呼妻倒空罍，数斟饮辄釂。","顿觉胸次豁，岂怀酗酣诮。","颓然百虑忘，浊醪信为妙。"]},{"t":"秋日寄乡中亲爱","f":"五言古诗","c":["秋气惨以慄，凉露日凄其。","感时忆亲爱，恻怆增遐思。","迢递隔山泽，悠悠各天涯。","念昔为舅甥，于今成路岐。","逝者间存殁，生者伤违离。","奈何绸缪意，中道失所期。","复兹邈千里，会合知几时。","抚事但心折，怀旧空神驰。","愿言垂暮景，黄发臻期颐。"]},{"t":"翠爽楼","f":"五言古诗","c":["幽居远城邑，山水有馀清。","层楼据其胜，登临怡我情。","曲阑无人来，卧起时独凭。","空青袭琴书，湿雾飘轩楹。","薰风涤烦襟，好鸟相和鸣。","景物能解颜，浊酒聊一倾。","油然既就醉，意适心自平。","多财信为累，达宦真虚名。","且尽今旦乐，明日非吾营。","愿言在槃涧，养素安馀龄。"]},{"t":"秋暑述怀","f":"五言古诗","c":["局促过长夏，荏苒届秋期。","初谓火既流，凉飙扫炎曦。","岂料残暑酷，乃尔不可支。","我膺徽纆缠，下共卒伍驰。","弱骨苦汗渍，弊衣叹尘淄。","一身方在公，宁复顾尔私。","虽无案牍劳，莫任奔走疲。","幸兹城南厂，颇与静者宜。","时来解襟坐，偃仰暂得怡。","我家文江上，先庐有遗基。","何当乞骸去，结茅树桐椅。","期与世尘绝，永随樵牧嬉。","怀哉果何日，浩叹徒歔欷。"]},{"t":"甲午九日病中作","f":"五言古诗","c":["谪官久于役，俯仰成陆沈。","岂顾岁时迈，但忧才弗任。","如何孱弱质，兹复病见寻。","萧条卧空宇，四壁但蛩吟。","山妻忽相谓，重九今旦临。","欲沽东邻酒，垂囊久无金。","而我听此语，浪然泪沾襟。","妇云奚所为，感慨亦何深。","拭泪向妇道，尔岂知余忱。","老亲隔千里，两鬓吴霜侵。","十年违菽水，惭彼返哺禽。","纵匪在忧患，有酒宁独斟。","妻亦重洒泣，悲感不自禁。","妇人亦人子，岂独丈夫心。"]},{"t":"秋日登雨花台","f":"五言古诗","c":["兹台创何代，遗址对远川。","雨花不复见，蔓草空翳然。","今晨逐徒侣，偶尔凌其巅。","一眄周四顾，梵宇相蝉联。","黄金佛铸像，玉麈僧谈禅。","侧闻身毒教，本自哀颠连。","谁哉继虞愿，浩叹秋风前。"]},{"t":"游朝天宫示同行道者","f":"五言古诗","c":["琳宫启森爽，荡荡寥阳天。","神君司雷霆，见者皆肃然。","翊卫俨六丁，陟降来群仙。","空歌发遥唱，秘笈开洞玄。","凤扶五老驾，龙骖列帝軿。","造化非形求，道妙岂言传。","希夷有像外，溟涬无始先。","愿随郁罗翘，稽首太上前。"]},{"t":"蒋节妇","f":"五言古诗","c":["萧萧斜日夕，肃肃悲风寒。","涓涓苦泪滴，寂寂孤灯残。","昔为比目鱼，今作独宿鸾。","捐生下相从，一死谅非难。","妾身岂足惜，老稚谁为看。","节义古所重，贫寠敢不安。","庶几泉路魂，瞑目少自宽。","泰山或可移，海水亦有乾。","惟应天上月，长照妾心肝。"]},{"t":"谒卞忠贞祠","f":"五言古诗","c":["粉署得休暇，偶登冶城巅。","令公有墓道，灌莽浮荒烟。","遗容俨鸾鹄，盛服严貂蝉。","褒赠恤典重，报祀时荐蠲。","缅怀临难日，力战操戈鋋。","君臣义所重，父子躯同捐。","岂伊一门间，卓尔忠孝全。","晋士轻节槩，放旷尚虚玄。","宜含瓦石者，视死犹生年。","炳焕留盛名，上与星日悬。","岂特式臣庶，端足扶坤乾。","嗟彼负国徒，亦拜祠堂前。","后来建康倅，允矣希其贤。"]},{"t":"题静观堂卷","f":"五言古诗","c":["嘿处在林居，沈冥遗世荣。","大哉灵台妙，止水湛澄凝。","括囊视群动，扰扰纷自营。","细草沿虚砌，佳木荫前庭。","虑空念乃息，欲净理益明。","如何驱驰子，终日沽其名。","清尊有醇醪，幽居无俗情。","醉来澹忘言，养晦乐馀生。"]},{"t":"望方山有怀","f":"五言古诗","c":["兹山如匣印，整特临都门。","傍顾众峰少，遥依钟阜尊。","烟岚结空翠，泉石生清芬。","木秀泽时雨，鹤归投暝云。","幽栖绝俗士，游衍皆仙群。","不见谢康乐，我怀谁与论。"]},{"t":"读道书作","f":"五言古诗","c":["疏林过微雨，绿叶当窗垂。","缅彼古仙者，秘言良难窥。","昼观探其赜，中夜梦见之。","玉色龙凤质，金章鸾鹤姿。","称云瑕丘仲，亹亹示端倪。","玄理贯而彻，素心欣以怡。","伊余烟霞性，早岁慕无为。","惊悟但虚室，飙轮那可追。"]},{"t":"谒赵文节公祠堂","f":"五言古诗","c":["烈焰不容熄，玉石俱凋伤。","宗社震荡中，大地多傍徨。","国祚倏云移，成命真靡常。","兴替虽有数，节槩焉可忘。","明公倅大郡，派系分天潢。","英气凌云霄，高操横秋霜。","俎豆固所闻，军旅非所长。","守土职攸重，固当死封疆。","小君贤伉俪，秉志与颉颃。","岂伊粉黛姿，乃有铁石肠。","所以颠危际，赖之植三纲。","精忠媲卞壸，庙貌俨相望。","义比华嵩峻，名齐日月光。","英魂在帝傍，时复临旧乡。","何代烈士无，岂独张睢阳。"]},{"t":"曾氏三贞堂","f":"五言古诗","c":["客行兰溪上，有屋甚炜煌。","借问谁所居，云是世节堂。","世节果何为，一门凛三孀。","三孀本一姓，婉娩金玉相。","父兄实佳士，夫子各才良。","于归期白首，中道俱沦亡。","韶华岂弗念，夙昔佩礼章。","捐生以相从，之死庸何伤。","此身宁足顾，老稚谁扶匡。","节义古所重，焉敢违纲常。","无贻九京羞，旌表非所望。","一孀逝已久，二孀政康强。","存者膺孝养，没者留芬芳。","而客闻此语，流涕忽沾裳。","寄言观风使，采之献明光。"]},{"t":"经浯溪读元结大唐中兴颂","f":"五言古诗","c":["平生念浯溪，镌镵有遗迹。","扬舲溯湘水，登临暂来即。","穹崖倚层云，奇险自天辟。","漫叟词既严，颜公笔无敌。","鬼神屡呵护，风雨长洗涤。","忠槩俨尚存，冰衔犹可识。","端容敛襟读，感慨重心戚。","谁画灵武谋，大物取何亟。","唏嗟中兴业，谅重君子惜。","逡巡解舟去，回顾三叹息。"]},{"t":"曲江拜张文献公祠","f":"五言古诗","c":["岭海号多士，开先始兴公。","大名照宇宙，信史书勋庸。","遂令曲江重，媲美中州崇。","精诚日星贯，俎豆春秋隆。","缅怀廊庙上，蹇蹇王臣躬。","指兹逆竖首，碎此干将锋。","天高听虽卑，竟莫回九重。","蓟野鼙鼓动，蜀道埃尘蒙。","范金肖遗像，褒赠劳渊衷。","顾瞻祠堂间，尚识风度雄。","白羽寓微意，金镜悬孤忠。","先觉百世师，景仰无终穷。","怀哉秉钧者，孰与公心同。"]},{"t":"游柳山书院","f":"五言古诗","c":["休政违炎方，返棹及清湘。","考图访前迹，怀古陟远冈。","礼殿丹垩陊，雩亭棘榛荒。","既感时代异，亦怜俎豆亡。","藓深碧侵阶，萝密青蔓墙。","雉鵙有翔集，衿佩无趋蹡。","阴菌依座秀，晴蕤沿涧芳。","岂伊诵弦地，而为樵牧场。","抚俗思贤哲，继轨念循良。","视废余诚怍，举坠职所当。","南藩如重践，庶或夙心偿。"]},{"t":"张节妇","f":"五言古诗","c":["昔与君结发，绸缪百年期。","奈何届中道，而有死别离。","相从固云易，九殒分所宜。","残喘匪自惜，呱呱谁抱持。","姆氏夙有训，敢或违天彝。","明明夫子魂，泉下谅有知。","少为张家妇，老作张家嫠。","先姑炳遗烈，誓欲与等夷。","他年树双表，大字旌门楣。"]},{"t":"重涖汴藩示流民","f":"五言古诗","c":["汴藩控西北，水陆咸此会。","太行如长城，巀嶪壮藩卫。","黄流自天来，荡潏势何锐。","土壤多肥美，风俗寡浮伪。","云胡遽凋弊，徵调靡宁岁。","富者化贫窘，窭者填沟浍。","十室数口存，一户百徭萃。","妇人废蚕绩，杼轴悉空匮。","丁男应夫匠，累载负租税。","偷生既难期，逃窜非所畏。","嗟我忝旬宣，重临益惊悸。","劳来固乃职，夙夕思尽瘁。","庶几解倒悬，疲瘵少苏遂。","矧兹圣明朝，屡下宽恤惠。","苦语示群氓，归哉理荒秽。"]},{"t":"九日郏县小蛾眉山拜二苏先生墓","f":"五言古诗","c":["风厉群木落，菊萸涵露清。","令辰届重九，促驾仍遐征。","逡巡及僧舍，整拂尘冠缨。","怀哉宋二苏，此地馀荒茔。","石人俱摧仆，垄土相将平。","趋祠拜遗像，祇荐陈芳馨。","缅彼蛾眉山，西望千里程。","兹丘亦何谓，云胡冒其名。","徘徊盻林壑，恍若闻金声。","感彼词垣仙，托此舍卫城。","文章白日丽，忠槩秋霜明。","徒令后来士，仰止生深情。"]},{"t":"蝻冢","f":"五言古诗","c":["七月月生魄，蝻出溱洧傍。","始焉学跃跳，倏忽羽翅长。","所过赭郊坰，矧复遗稻粱。","坐令饫饱腹，立化饥馁肠。","督民殄斯类，晨夕纷遑遑。","隳突践垄亩，炬火明山冈。","燎焚弱质烬，扑击微骸僵。","卒夫载朽胔，络绎持筥筐。","穿穴掩腥秽，作冢官道傍。","罪浮彼破镜，虽死安能偿。","蝮蛇实摇毒，已疾传医方。","蜜蜂诚小物，亦解奉其王。","畜蚕必吐缕，世赖充衣裳。","畏蚊恐噆体，帱幕席与床。","青蝇奚足憎，赤虿应可防。","编竹蚁知报，勤诵萤聚光。","致雨蜥蜴验，起痹全蝎良。","原性殊善恶，稼穑咸无伤。","惟兹口吻酷，黍稷争先戕。","乾坤百虫夥，去尔庸何妨。","吾将告宰造，投畀魑魅乡。","从今乐耕凿，岁岁歌丰穰。"]},{"t":"崇福宫祷雨","f":"五言古诗","c":["清晓戒徒御，祷雨谒道宫。","焚香古帝前，拜跽肃以恭。","因之感兴亡，华构久已空。","尚有敕赐碑，狼藉蔓草中。","慨想宋全盛，銮舆屡游从。","名臣领祠职，列辟俨睟容。","运往物随改，伟观难再逢。","登临睇烟霞，颇惬眺望悰。","迟回不能去，树杪来长风。"]},{"t":"观启母石","f":"五言古诗","c":["夙负山水癖，苦乏幽讨缘。","幸兹崧与少，秀色当眼前。","公馀陟峻冈，忽睹石一卷。","特立四无邻，觚棱不相联。","云是启母身，化在郊墟壖。","呼之乃擘裂，启出仍完全。","幻语本荒唐，昉见淮南篇。","遐想覆载间，沧桑屡更迁。","安知运代移，坠彼千仞巅。","厥理诚可推，贤达固释然。","矢诗正妖讹，昧者庶或悛。","后世有豪杰，为我焚其篇。"]},{"t":"端午日游少林寺","f":"五言古诗","c":["少林耸岧峣，有路达葱岭。","半生怀胜槩，老乃贱真境。","缁流远见迓，偏袒仍露顶。","升高纵遐观，颇觉痴缘屏。","蒲风翻卷帙，艾色侵衣领。","掇蔬僧具供，饮骑童汲井。","自拈清净香，作礼爇古鼎。","超超昔神师，顺寂同溟涬。","而于片石上，留此不灭影。","竺夏虽异辙，皆贵能猛省。","寒岩许分坐，禅定毕馀景。"]},{"t":"题王生卷","f":"五言古诗","c":["王生事众艺，厥艺非庸常。","字格既超俗，医名将擅场。","挥翰缙绅前，悬壶阛阓傍。","时时拂华笺，流丽两三行。","劲健束筋骨，端圆敛锋铓。","砚池墨波翻，药阑杏阴凉。","家藏总秘帖，囊贮皆奇方。","勉力当师承，蜚英期颉颃。","诚心见焚劵，清致归文房。","八法右军最，诸科思邈良。","笼鹅与伏虎，万古同垂芳。"]},{"t":"题双燕图寄表弟陈安行","f":"五言古诗","c":["君家唫溪北，我家郡城西。","君家梁间燕，我家梁间栖。","我从出镇来，寒暑又三变。","不见故乡春，惟见故乡燕。","挈家吉城边，寓家汴河湄。","燕识主人心，相随不相离。","念君千里隔，见君几时得。","欲令燕衔书，飞归到君侧。","君能弗吾弃，为理白云庄。","愿言共君老，看燕双飞翔。"]},{"t":"雪中偶至相国僧舍","f":"五言古诗","c":["精蓝创何朝，规制极殊胜。","阎浮罹劫火，无复庄严盛。","惟馀白足僧，短褐露两胫。","我于大雪中，独立偶乘兴。","难寻金布地，颇讶玉为径。","娑婆绝尘翳，似得天眼净。","冷冷梵呗音，细杂铙与磬。","欣然遂忘返，宿留逮昏暝。","乃知向上机，无台亦无镜。","徒劳费辞说，妙在悟自性。","世无毗耶翁，孰拯众生病。","愿言投空门，跏趺事禅定。"]},{"t":"梦萱堂","f":"五言古诗","c":["忆昔种丹棘，期以怡亲衷。","亲亡故物在，徒使增悲悰。","朝观夕仍对，讵料精诚通。","忽从枕上见，宛与生存同。","欣然载言笑，睇彼阶下丛。","森森鹄觜英，相映慈颜红。","芳茎挺清脩，嫩叶纷葱茏。","斓斑五采服，煜比花色浓。","宜男既非望，且遂忘忧忡。","惊寤忽无睹，寥寥书室空。","想像抱沈痛，泪落如流淙。","起视北堂植，青青凉露中。"]},{"t":"青城怀古","f":"五言古诗","c":["炎宋尚简质，郊丘布为墙。","九门谨阖辟，万卒严周防。","暂置弗劳杵，权施岂须隍。","绵延逮宣政，骄盈更典章。","版筑易缕制，墉壕固金汤。","衮龙狩沙碛，泥马奔钱塘。","奢侈谅宜戒，播辱尤所伤。","陶匏荐明水，维馨仰前王。"]},{"t":"林亭远眺卷","f":"五言古诗","c":["双亲久沦逝，遗榇空山藏。","岁月谅已远，抚昔增感伤。","仪刑渺何之，想像空徬徨。","悠悠人子心，沈痛何时忘。","虚亭纵遥览，竹树森微茫。","轻云敛还舒，列岫纷低昂。","岩松布清阴，溪艇浮沧浪。","骋望极遐旷，白首在异乡。","邈兹九京隔，慨叹徒深长。","行行更回顾，泪下沾衣裳。"]},{"t":"老大心易感鞠育恩难酬顾瞻青青山高冢山西头憩兹灌木阴盻睐驰双眸含悲睇天末若见坟与丘茅亭依水石屡至成淹留萧萧风树枝欲静不自由哀哀乌鸟情缠绵终靡休焉用徒耳为显扬慎所修移忠古攸贵往哲有令猷","f":"五言古诗","c":["先垄违别久，蔓草迷荒墟。","岂不念洒扫，道路频驰驱。","独悬一寸心，怵惕霜露馀。","王门固可乐，窈窕曳长裾。","旨甘亦云足，弗逮将何如。","孤怀倍恻怆，引睇西城隅。","洪涛曷能度，叠嶂谅难踰。","归飞乏羽翼，注目空踟躇。","中和盖代英，玉质神仙癯。","诗画两精妙，风韵天然殊。","熙春富词藻，字字皆璠玙。","允为世三绝，勖尔当珍储。"]},{"t":"重庆堂为钱仪宾赋","f":"五言古诗","c":["客行大梁道，华屋枕道傍。","借问谁所止，阀阅何炜煌。","居人笑答言，此谓重庆堂。","就中两遗婺，同志如雪霜。","贤孙英俊姿，遴选宾天潢。","膳调三鼎珍，乐奏丝与簧。","笄珈俨成列，冠佩肃分行。","趍跄二亲侧，次第进杯觞。","百务弗相干，暮齿弥康强。","家和福乃臻，四序来祯祥。","玩匪宜男花，心怡自忧忘。","姑耆妇仍寿，钧享百岁长。","客闻遽前拜，重是双贞良。","岂徒垂阃则，庶以敦纲常。"]},{"t":"送杨郎中催马草还京","f":"五言古诗","c":["大梁据中土，自昔风气旺。","北邙殊蜿蜒，太室极雄壮。","黄河贯其间，浩浩恣奔放。","四野开平衍，桑柘绿相乡。","丁男事耕耨，姑妇治丝纩。","菽麦盈仓庾，醑醴溢盆盎。","近岁颇凶屯，旱暵觖农望。","念兹饥馁馀，十室九鳏旷。","长贫负租税，远役困夫匠。","督刍实赖公，区画咸适当。","深体尧舜心，推仁悯凋丧。","叱咤尚弗忍，矧肯施鞭杖。","愧余谫劣才，旬宣乏善状。","竭力奉宽条，庶减疲癃恙。","赠别陈民艰，冀君彻卿相。"]},{"t":"拟古十四首 其一","f":"五言律诗","c":["玄穹惟湛寂，元气斗斡旋。","时序相禅续，阴阳无忒愆。","乾纲后攸则，庶政相斯专。","明良职其职，四海自熙然。"]},{"t":"拟古十四首 其二","f":"五言古诗","c":["吾观日与月，乃是阴阳精。","彼升此攸降，循环有常经。","万方仰临照，元良则其明。","离躔遂晦蚀，惟辟修德刑。","玄象虽缅邈，人当思戒惩。"]},{"t":"拟古十四首 其三","f":"五言律诗","c":["园绮遗世贤，逍遥商颜巅。","安汉笑谈顷，视之何易然。","拂袖谢隆准，采芝茹芳鲜。","今复有斯士，吾将为执鞭。"]},{"t":"拟古十四首 其四","f":"五言律诗","c":["黔娄贫贱士，怀道栖衡门。","布被斜可殓，曾西徒失言。","终焉谥康子，万古播清芬。","云胡有千驷，殁世寂无闻。"]},{"t":"拟古十四首 其五","f":"五言古诗","c":["吾观古颜孟，生民之先觉。","已克礼斯复，陋巷亦云乐。","气由养而充，浩然塞寥廓。","其殁馀千年，载籍犹昭灼。","天爵良可珍，箪瓢未为恶。"]},{"t":"拟古十四首 其六","f":"五言律诗","c":["方寸湛明鉴，贤愚罔弗然。","浸淫汨私欲，沈溺陷危颠。","善性宁终昧，清光应暂捐。","勉旃力磨治，皎洁当如前。"]},{"t":"拟古十四首 其七","f":"五言古诗","c":["芙蕖开清池，花叶相掩映。","粲然薰风中，容色自娟静。","瑩同淑女姿，直类君子性。","岂不念春华，荣悴分攸定。","奈何徒征驰，竟日事奔竞。"]},{"t":"拟古十四首 其八","f":"五言律诗","c":["蹁跹一黄鹤，飞止弱水宫。","青鸟戴胜使，侧目不相容。","遂遗瑶池迹，远寄沧海踪。","无心随鸿鹄，任尔摩层穹。"]},{"t":"拟古十四首 其九","f":"五言律诗","c":["闻昔有逸民，风标何峻拔。","超然凌云霓，遐视九垓狭。","迹虽戾中道，心则忘穷达。","其人谅可希，前进脂吾牵。"]},{"t":"拟古十四首 其十","f":"五言古诗","c":["索居人事寡，穷探坟与丘。","多谢东邻客，频来为我谋。","乃为儒冠误，富贵别可求。","首干中常侍，次谒北平侯。","捷哉仕宦径，贸贸不知由。","读书果奚益，辛苦被时羞。","我笑而相答，志殊各自求。","萧条老布褐，道在复何尤。"]},{"t":"拟古十四首 其十一","f":"五言古诗","c":["忆昔中园里，樟楠柯叶深。","芳葵种其下，幽郁冒繁阴。","靡瞻朝暾出，鲜觌夕景沈。","纵昧昏旦候，宁殊倾附忱。","小草本非异，怀忠性所任。","谁当抑蒙翳，庶遂向阳心。"]},{"t":"拟古十四首 其十二","f":"五言古诗","c":["森森邓林木，四序恒青苍。","随材就抡择，规矩因圆方。","其中有孤桧，肤理尤坚刚。","挺特寡附丽，辛苦受雪霜。","含章少外饰，莫厕栋与梁。","美哉连抱姿，而弗登明堂。","永惟松楠侣，耻在槐樗行。","志士不苟屈，抚树空徬徨。"]},{"t":"拟古十四首 其十三","f":"五言古诗","c":["我本贱贫者，栖栖在蓬茨。","蓬茨何所乐，吾心自孳孳。","人言青山巅，玉髓閟在斯。","服食仙立成，深惭禀凡姿。","何如任其性，隽味古文辞。","仰止曲肱叟，舍此吾谁师。"]},{"t":"拟古十四首 其十四","f":"五言律诗","c":["荒哉炀天子，纵侈乐无涯。","彝纪胡可渎，同心赐宣华。","独孤虽云误，勇才亦非佳。","杨梅枯已久，抚事令人嗟。"]},{"t":"阙题","f":"五言古诗","c":["先生笃行士，小隐南麓边。","芥视功与名，遗弃如浮烟。","造门非俗流，问字皆英贤。","室空长物无，匡床但青毡。","世受静春学，潜心最精专。","所以绝外慕，昕夕劳钻研。","斯文诚在兹，乐矣卒岁年。","海㝢忽鼎沸，群氓弄戈鋋。","渠魁何狂愚，驰书敢相延。","奋袂拂然起，仰首呼青天。","谁为夺我志，清白世所传。","洒然携琴剑，乐道鉴鱼鸢。","从此勿相逼，清风激寒泉。","当此丧乱际，三纲赖公全。","磊落贞松姿，霜雪愈挺然。","九京不可作，星日芳名悬。","因诗寄深衷，叹息颓阳前。"]},{"t":"题方方壶枯木竹石图","f":"五言古诗","c":["空山百尺树，质性何贞坚。","夭矫修篁侧，寂寞磐石边。","亭亭任重姿，屹立思擎天。","造化偶遗弃，值彼蓬莱仙。","写之若怜才，峥嵘老龙骞。","朔风振群木，节操欣独全。","寄言玩物者，毋贵春花妍。"]},{"t":"颜用正挽诗","f":"五言古诗","c":["幽栖忘声利，抗志惟云泉。","澄神以内照，白首甘草玄。","既混钓耕侣，讵希冠盖贤。","魄化名未泯，尘凝榻尚悬。","服膺先民训，委顺安其天。","诔文太史述，遗经门人传。","息荫树绕屋，资生瓜在田。","掩棺谅靡憾，况乃获归全。","孔曾皆一辙，此理岂今然。"]},{"t":"哭子","f":"五言古诗","c":["余龄及中岁，有子生六年。","疾痛母心惴，寒饥我怀煎。","鞠育爱虽切，薰陶教宜先。","数日近方解，诵诗未能全。","赋龄亦何短，夭阏辄弃捐。","触目恨山积，沾衣泪河悬。","世泽惧斯斩，书香赖谁传。","嗣续人所重，念之增惕然。","修已安义命，昊穹谅无偏。","明丧笑商鄙，情钟惭衍贤。","螟蛉信么么，在物亦堪怜。"]},{"t":"夏末偶寻洞惠道院","f":"五言古诗","c":["晓起凉月淡，絺衣坐肩舆。","洒然尘虑豁，遂即道者庐。","萧条殿廊存，亭轩化荒墟。","山门憩樵农，藓砌鹿豕趍。","霤倾有堕瓦，树伐无遗株。","仙家尚消沉，况乃俗士居。","蓬莱屡清浅，此事谅弗虚。","吾闻至人言，一气运化枢。","莫窥机缄微，孰外定数拘。","通由饥亡命，载以贿丧躯。","荣华岂久在，役智悲群愚。"]},{"t":"洞章二首 其一","f":"楚辞体","c":["缥缈大梵境，玉京何寥寥。","空洞无色根，泛兮若浮飘。","阳精镇朗耀，岂复知昕宵。","熣灿丹霞中，浩歌白云谣。","一听众缘息，再聆群累销。","劫运自兹度，稽首登神霄。"]},{"t":"洞章二首 其二","f":"五言古诗","c":["浮黎始上青，浩气长空濛。","溟涬窈无朕，端倪那可穷。","梵川玉虚界，不与诸天同。","群仙时遨游，翳凤驾赤龙。","年寿罔有极，莫能测其终。","泛咏黄云里，肃侍弥罗宫。"]},{"t":"题翎毛画赠叶太守","f":"五言古诗","c":["名郡太行北，水陆当要冲。","舟车日旁午，来往无停踪。","民贫困迎送，矧值岁罕丰。","褴缕衣百结，藜藿恒弗充。","前年太守来，遴选出圣衷。","下车亟摩抚，昕夕劳其躬。","还珠及渡虎，有待臻全功。","我昔因入觐，道经淇水东。","解鞍憩驿舍，桂树空庭中。","有鸟鸣树间，其雌和其雄。","物既适至性，人犹含苦悰。","尚期尽生遂，和辑比鸟同。","庶令盛明代，再见黄与龚。","托画表深意，宁论描写工。"]},{"t":"丙寅端阳述怀","f":"五言古诗","c":["岁月易流迈，佳辰届端阳。","闲居昧时序，节日如平常。","空园积雨霁，蒿艾如人长。","萧条掩关卧，蝶梦方悠扬。","老妻唤我起，盘饤劝我尝。","小孙颇慧黠，学语声琅琅。","举目见之喜，欣然挥一觞。","俭约固予分，泰侈非所望。","冥观阴阳运，隆替乃其常。","吾生幸休退，用舍安行藏。","前修有善训，岐路多亡羊。","且复醉蒲醑，毋将忧自戕。"]},{"t":"丙寅初度作","f":"五言古诗","c":["余生如稚松，由寸望百尺。","既承雨露滋，亦受霜雪积。","蹉跎踰七十，勤苦曾备历。","误蒙明圣知，谬忝中外职。","顾已惭菲薄，于时乏裨益。","处盈亏必随，履泰否斯即。","至理谅在兹，昧者固弗识。","叩阍乞残骸，休退恩旨锡。","遂令犬马躯，获返田野迹。","长揖画省僚，重负从此释。","今辰届初度，厨传仍岑寂。","傍人竞嗤笑，穷约犹曩昔。","妻孥颇愧赧，而我固悦怿。","平生守儒素，晚节敢变易。","回思永乐初，岁月类梭掷。","同年四百馀，多已在鬼域。","存者才十辈，犹被利名役。","迂疏独何幸，林下得偃息。","遗荣遂安闲，养静忘跛躄。","游鳞泳清波，羁鸟敛倦翼。","贫非吾所忧，病岂吾所戚。","宠辱与升沉，宁复置胸臆。","忘机侣鸥鹭，植杖随沮溺。","浩然天壤间，俯仰惟意适。","长歌自为寿，坐对远山碧。"]},{"t":"亡友舒州通判张君哀挽诗","f":"五言古诗","c":["我昔游禾州，英俊森跌宕。","众中昉识君，彼此年盛壮。","定交文字间，倾倒已见谅。","推能实居先，论齿仍在上。","既欣气味同，复喜怀抱旷。","温温璞玉姿，浩浩江海量。","岂惟邑校雄，允谓士林望。","及门师易庵，卒业侍函丈。","大哉四圣经，研究彖与象。","袖然西江魁，足继宋陈亮。","诸生老场屋，颡泚羞倔强。","词垣七八年，葭玉得倚傍。","编摩互论讨，疑惑共咨访。","但期荅君亲，未省谒卿相。","佞色从古鄙，直躬岂今尚。","始屈倅邦畿，翻能拯民恙。","公平村有谣，苦澹宦无况。","何期寒窭家，忽被仁惠贶。","云胡去郡亟，遂使失保障。","一官滞房山，连岁董夫匠。","令名诸公推，敏识多士让。","政须峻升迁，溘尔遽凋丧。","呼天邈不闻，为善匪可仗。","缙绅竞悼伤，舆隶亦惆怅。","而我忝深知，肝胆两相向。","切偲失箴规，磨琢废炉荡。","情捐骨肉亲，序缺兄弟行。","前修不可作，后进日流荡。","哀哉若人亡，士习趍谬妄。","纷纷夸毗子，翻覆千万状。","譬犹蚁附腥，缭绕沿瓮盎。","畴能遏颓波，奚忍鼓其浪。","孰知余心悲，孤立谁我相。","令仪隔幽明，清梦劳想像。","作诗述初终，老泪恣横放。"]},{"t":"春湖黄处士挽诗","f":"五言古诗","c":["富顺山水好，春湖更无双。","波澜势浩荡，昕夕声淙淙。","黄公英特士，奇气未易降。","揭兹以自号，传呼遍乡邦。","雅怀乐幽胜，临流辟轩窗。","课儿夜读书，短檠灿银缸。","六经窥窔奥，百氏删纷哤。","鱼龙每来听，出没相舂撞。","有时岸纶巾，陇头看飞龙。","有时狎鸥鹭，沿洄棹轻艭。","彷佛盘谷李，依稀鹿门庞。","几年厌世去，高坟屹崆㟅。","苔藓翳翁仲，松筠列旌幢。","芳名媲九鼎，千夫莫能扛。","遗泽岂终竭，深长配岷江。","伊人逝已久，挽歌富新腔。","丰碑著潜耀，尚待笔如杠。"]},{"t":"题感螺诗卷","f":"五言古诗","c":["叙州富顺县，孝孙有黄璿。","弱龄方及纪，至性出自然。","祖母久遘疾，伏枕嗟沈绵。","绛宫鼎沸溢，荣卫热相煎。","饮药如饮水，终剂弗少痊。","颇思泥淖螺，煮食或可蠲。","时当十月末，凛如冱寒天。","陂泽各已冻，此物求无缘。","孝孙默致祷，径走南塘边。","南塘路迢递，心急足不前。","匍匐至其处，解衣漉清涟。","果获四十馀，绀若佛髻圆。","持归更涤濯，爇火烹甘泉。","调以醯与酱，芬香绝腥膻。","病者见之喜，饮啜随下咽。","燥烦遽脱体，阽危遂安全。","乃知一念诚，可以格上玄。","造化宰报施，锱铢宁使偏。","孙今陟显位，实秉郡守权。","兹事谅非妄，词林钜公传。","矧伊职师帅，表率宜身先。","永言锡尔类，咏歌继朝贤。"]},{"t":"题张教授居易轩","f":"五言古诗","c":["行已素其位，彰彰先训明。","美哉留侯裔，守分息营营。","执经侍彤邸，讲读倾忠诚。","一室无赢积，四序有馀清。","孰云禄秩薄，岂受吏事婴。","财丰真为累，官达仍贻惊。","惟当乐夫天，优游心自宁。","永言慎终始，俟命歌隆平。"]},{"t":"别子钦刘同年","f":"五言古诗","c":["庐陵汉名县，黉舍当城南。","粤从宋庆历，杰构何潭潭。","穹碑泐学记，欧子亲题衔。","所以富才彦，挺然皆梓杉。","游歌我昔忝，遗经事穷探。","英俊非不多，畏敬踰四三。","子谟与德让，奋起师易庵。","晨夕久薰炙，化雨深濡涵。","王门职辅导，胄监峨弁簪。","引之绝温润，钦止精研覃。","之宜暨仲举，问学青于蓝。","惜未及贵寿，早终四子咸。","笃实若陈李，磊落俱奇男。","雄藩佐邦伯，经筵进封函。","就中最杰特，子钦文不凡。","壁经世授受，道腴恣沉酣。","聱牙古盘诰，同异互订参。","他人悉窘步，君独行眈眈。","翰林俊声著，粉署刑名谙。","冰檗岂论苦，澹泊夙能甘。","擿奸若风厉，谳狱同春含。","譬之龙泉剑，光焰不可缄。","契阔五六载，相思隔烟岚。","追怀旧游地，几度联归骖。","兹焉幸一会，壮志仍岩岩。","胸襟豁湖海，论议森戈锬。","藩臬诸钜公，招邀列罂墰。","肥牲刺羊豕，佳味罗蛤蚶。","鲙鲜旋烹鲫，醢美细脔䳺。","玉棋圆叠蔗，金丸满堆柑。","蔬茹剪霜韭，竹萌掘冬䈄。","酒渴漱茗饮，齿寒嚼菹蘫。","叨陪接几席，答问吐乡谈。","清言霏玉雪，倾听我所贪。","亹亹续弗绝，有如吐丝蚕。","握手万里外，绸缪乐且湛。","胡为又分袂，行李僮仆担。","于时一阳复，两鬓风毵毵。","东坡昔跋涉，渡海再迁儋。","未久即见召，还朝貌逾傪。","寂寥数百载，继武惟子堪。","岁寒见松柏，大厦待楩楠。","赋诗写缱绻，空言只增惭。","情深觉词赘，此意谅余监。"]},{"t":"枇杷晚翠","f":"五言古诗","c":["江南有佳植，名列果品中。","仙郎乃独好，官舍亲培封。","亭亭异众卉，秀茂当严冬。","深绿冷逾茂，繁青寒更浓。","满树叶葱茜，阴森密成丛。","岁晏不改色，傲睨雪与风。","所以玩物者，爱比松柏同。","灌溉役舆隶，赋咏劳群公。","人物两奇特，永言播无穷。"]},{"t":"即事","f":"五言古诗","c":["功名事恬退，求志在云泉。","性本寡谐俗，遂此遗世缘。","瘠壤百馀亩，草屋数十椽。","耕耨有閒暇，北窗高枕眠。","人生慕富贵，方寸徒忧煎。","百年谅能几，倏忽成华颠。","种秫酿美酒，庶以醉自全。"]},{"t":"题商山四皓图为陈徵士致广题","f":"五言古诗","c":["昵昵戚姬宠，胶胶如意怜。","壮哉盘石基，凛将殒而颠。","睿志慝深惑，嘉猷忌谠言。","辅臣谋已拙，壸阈忧徒悬。","遐飞四威凤，千仞来翩翩。","赖以为羽翼，大本安且全。","翻然振归翮，遥想商山还。","兹事已云远，高风图画传。"]},{"t":"郡庠古柏行","f":"七言古诗","c":["泮宫翠柏真奇特，溜雨霜皮古铜色。","共传贤守李侯栽，年数于今过三百。","几经劫火幸仍存，草木犹依圣教尊。","清覆讲堂闲永昼，密笼礼殿翳香云。","芳根长托弦歌地，坛杏庭槐共生意。","春风摇影漾宫墙，午日流阴上庭砌。","博士鸣鼙散学徒，竞来树底纵歌呼。","乔柯宁集接舆凤，细叶争巢朱博乌。","却怜种者今何在，留得青青表遗爱。","文风化雨沾濡深，从宋历元逢盛代。","上摩北斗凌中台，时有佳气相徘徊。","大哉宣尼后凋训，珍重明堂梁栋材。"]},{"t":"潢溪钓者逸闲轩","f":"七言古诗","c":["白发潢溪钓游者，半生浪迹栖林野。","已惯为农夜饭牛，宁能执策朝驰马。","只知物外无喧嚣，养花种树东津桥。","纵横坐席杂樵牧，倾倒瓮盎忘晡朝。","醉来就床且高卧，一枕从教日西堕。","盖世功名逝水流，薰天富贵飘风过。","烟霞泉石聊徜徉，青云要路非所望。","乃知静处有真乐，却笑时人何太忙。"]},{"t":"陈上舍所藏蔡主事墨竹","f":"七言古诗","c":["粉署政闲聊自怡，运毫濡墨写竹枝。","宋时二子谁最好，今日诸公君独奇。","露梢风叶新图里，丛色翛翛紫鸾尾。","郎官醉笔扫将成，上舍高情得之喜。","明窗净几绝纤埃，袅袅长竿若可裁。","白昼闲将堂上挂，丹山定有凤飞来。"]},{"t":"高道士所画山水","f":"七言律诗","c":["伊谁丹青擅能事，画出群山与山似。","树杪如闻雪瀑泉，林间疑有云门寺。","杖藜桥上知何人，抱琴可望不可亲。","高师指点笑相语，我昨图成殊逼真。"]},{"t":"赋得小孤绝壁送人还乡","f":"七言古诗","c":["海门砥柱长江浒，东南群流皆下经。","荡摩霄汉压溟渤，镇控吴楚资神灵。","百丈悬崖寔奇壮，银涛雪浪相舂撞。","层颠俯视飞鸟背，曲径斜通白云上。","中有重渊龙伯都，琼宫贝楼如玉壶。","天晴蜃气秋成市，月冷鲛人夜泣珠。","羡君归去过其地，政好登临骋遐睇。","贾客争祈天姥祠，妖巫谩设彭郎祭。","解缆开舟肯暂停，乘风破浪如流星。","明日思君不可即，天涯惟见此山青。"]},{"t":"送周大尹复任清河","f":"七言古诗","c":["分阳令尹宜峻迁，铜章墨绶却仍前。","东风上林白鼻马，细雨韩桥画鹢船。","桃源过来是花县，闻道吏民怀宓贱。","别处城下草生初，到时邑中柳舒遍。","奔流忽见浊清痕，岸上人家是郭门。","郁葱王气濠梁近，迢递官程淮汴分。","羡君佳政人不如，两临百里驰芳誉。","剩将此际循良迹，留待他年史馆书。"]},{"t":"送张教授改任凤翔","f":"古风","c":["客舍暄爱日，旗亭冽霜风。","故人有远宦，策马之关中。","识君今馀十五载，几度思君梦华采。","别后音徽烦屡寄，交谊重逢不曾改。","似君才调世岂多，手援健笔如挥戈。","门生问字每载酒，道士写经频送鹅。","九年作官南海上，文与波澜相浩荡。","今为冷椽向凤翔，岐山渭水周故疆。","陇云秦树真可画，绛帐横经复闲暇。","座上青毡自足娱，眼前白发何须怕。","我本疏狂迹不羁，与君情好最相知。","殷勤不劝杯中酒，寂寞徒吟卷里诗。"]},{"t":"琴清轩","f":"古风","c":["野客本冲素，瑶琴何静渊。","层轩久绝俗士迹，绿绮自上朱丝弦。","初弹徵调声古淡，泽国苇寒鸣旅雁。","再弹宫音如逆泉，冰盘乱走珠玑圆。","斯须改调羽仍角，洒洒明珠相续落。","秋冷潇湘见断云，春和鸾凤鸣阿阁。","吾闻伯牙昔善琴，后来不复传遗音。","如何到处听者少，悠悠山水空高深。","银筝锦瑟人同喜，流荡娃淫悦俗耳。","卫国谁知击磬心，齐门孰识吹竽耻。","三尺焦桐只独怡，希声大雅世岂知。","但令妙解徽弦趣，不必黄金铸子期。"]},{"t":"送刘博士从征交趾并贻梁御史邓主簿","f":"七言古诗","c":["沛中才子容台客，半世经行遍南北。","去年随驾猎长杨，今岁从征破残贼。","从征还得侍青油，中军帐前参密谋。","盾上频看草文檄，军前屡见获俘酋。","梁侯邓簿皆同调，对酒筵开能谑笑。","綵笔宵成露布辞，紫泥晓下班师诏。","论功大将画麒麟，先数风流幕下宾。","豸冠行拜劳还宠，乌府仍称献纳臣。"]},{"t":"湖山佳趣歌","f":"七言古诗","c":["半生甘作隐者流，两屐不到侯门游。","老去高情付林壑，闲来乐事只渔舟。","春水泛花漾孤屿，杜衡蘼芜满脩渚。","晴树远连江上村，晚云忽作溪南雨。","自怜身世两悠悠，濯缨濯足忘吾忧。","万钟悬爵本非志，一竿在手何所求。","门前学种五株柳，逸兴雅怀到处有。","对客石床抚古琴，留客山瓢斟浊酒。","年年岁岁适闲情，皞皞熙熙度此生。","已无天上鹓鸾梦，且结湖边鸥鹭盟。"]},{"t":"兰秀轩","f":"七言古诗","c":["闻种幽兰在庭际，争秀竞芳如谢砌。","客来谈诗坐高堂，入帘飘席但闻香。","宣尼绿绮寄三弄，屈子离骚歌九章。","岁寒不凋复不悴，夏芷冬荪宁足贵。","此花芬馥淡且清，愿尔诸郎同德馨。","善人比洁真无愧，燕姞为祥良有徵。","风轻露冷美闲夜，更爱国香长绕舍。","轩中有兰人好看，图上看兰空是画。"]},{"t":"送缺生还乡","f":"七言古诗","c":["羡子翩翩世莫测，三十今犹隐乡国。","陈平非是困长贫，贾谊终当射奇策。","于今应暂赋闲居，钓水樵山心自娱。","甘旨时供二亲养，灯窗夜对一床书。","昨日公车召尊府，青云有官未曾补。","天涯岂但鞅掌劳，膝下惟知别离苦。","岁月蹉跎会面违，回头又复念重闱。","柴门落照迎归客，童稚升堂竞挽衣。","有才勿向山林老，功名在人须及早。","胡为寂寞环堵中，穷巷年年长秋草。"]},{"t":"题徐太守所画掀蓬梅花图","f":"七言古诗","c":["纷纷卉木凋零早，独有江梅冬更好。","天寒岁晏风泠泠，野桥无人流断冰。","南枝烂漫北枝少，恍如玉貌千娉婷。","酷怜随月印沙影，更爱临崖近水形。","当涂太守今黄霸，名重华光补之亚。","酒酣自写复自题，馀子持缣终不画。","初开盛吐俱含态，将飘乍落皆有情。","玲珑轻霰簇镂玉，荡漾明珠叠碎琼。","昨来卢君新卷里，写得长梢最妍美。","疏蕊凌寒似得春，暗香扑鼻疑生纸。","世间画手多凡流，惟数徐君笔最优。","不必掀篷棹飞雪，观图何异在扁舟。"]},{"t":"送周生还文江","f":"七言古诗","c":["周生磊落志不群，馀子纷纷那足论。","书香道国先贤裔，宦谱平园丞相孙。","少小聪明已堪惜，烱烱双瞳剪秋碧。","当代诸兄固罕俦，往时严父真勍敌。","江乡屈指擅声称，青云步武宜相承。","致身要展胸中略，闭户宜穷窗下经。","男儿猷为贵闻早，万事无如盛年好。","伫看唾手取功名，莫遣低头叹衰老。","兹行赋归何时来，元方迟尔黄金台。","勿随斥鴳藩篱下，枉却骅骝泛驾材。"]},{"t":"送陶给事升闽宪佥事","f":"古风","c":["江上草新绿，都城春雪晴。","玉缸携酒共君饮，红亭醉醒空离情。","问君此行何慷慨，揽辔超超渡闽海。","青琐多年旧有声，赤心一片终难改。","玉节观风八郡倾，人人同仰范滂名。","陶潜解印身虽逸，桓典乘骢众所荣。","判袂相望不知久，渺渺青山重回首。","别后含情空忆君，谩对萧条白门柳。"]},{"t":"赋得海门潮信送黎慎之还乡","f":"七言古诗","c":["海门荡潏深千丈，潮去潮来如有期。","夕阳欲没退偏早，晚月乍升生太迟。","退早生迟自无爽，行人到处占消长。","终年空打崩浪矶，半夜遥通女儿港。","清淮不泛鸱革魂，潜来默去朝复昏。","汀洲但见沙禽迹，岛屿惟馀石藓痕。","黎君晏岁乘潮去，路指海门奇绝处。","览胜应知造化工，吟清信得江山助。","解缆开帆举画桡，溯流激浪随风飙。","回首行人不可见，往来惟见海门潮。"]},{"t":"题施生吴山图","f":"七言古诗","c":["伯鸾自安田野性，季鹰谩有莼鲈兴。","何似施生住日边，吴中山水壁间悬。","山水苍苍绝垢氛，看图不异在吴门。","亭间一叟书长把，树杪飞流响不闻。","苍苔白石菰蒲绿，溪上谁人补萝屋。","数拳晴雪见栖鸥，十亩凉阴翳高木。","我昔巢栖五老颠，松风桂月伴云泉。","朅来委质事明主，敢念池鱼思故渊。","瑶枰谩想溪边奕，碧草空怀洞里眠。","缄情划尔发长笑，清宵梦绕香炉烟。"]},{"t":"题意上人卷","f":"七言古诗","c":["意公优游乐禅寂，独鹤片云比踪迹。","半世辞家念已忘，诸方乞食人皆识。","水月观心无减增，曾参达磨礼卢能。","手持解脱千年锡，口诵楞伽万变经。","风幡不动空缘业，深悟菩提赖言说。","慈性圆融任去留，幻身聚散轻生灭。","我欲归投选佛场，蒲团贝叶共禅床。","金螺山下寻莲社，白鹭洲前结草堂。"]},{"t":"送张生游金台","f":"古风","c":["幸遇太平日，观光快嬉敖。","春衣白鸠舞，煖帽青貂袍。","都城列雉森崇墉，荣光喜气何葱葱。","风云观阙异人世，皞熙自与华胥同。","张郎英年频此游，凭高吊古穷冥搜。","卢沟晓月带冰渡，易水秋风终岁留。","豪来得意金不惜，秦楼楚馆皆相识。","飞觞醉杀青蛾眉，红锦缠头恣抛掷。","词垣銮坡总钜公，古文奇字比扬雄。","填门请谒不轻予，挥洒淋漓盈卷中。","卷中题咏真奇绝，珠贝晶荧玉重叠。","夜郎谁数李青莲，湖海诗声久消歇。","南来北去屡往还，半生多在江淮间。","经行到处且歌笑，莫教辛苦愁朱颜。","愁朱颜，易萧索，大夫慎勿念功名，紫马驮钱买欢乐。"]},{"t":"题三友卷","f":"古风","c":["世人结友结货利，知君结友与人异。","半生缔交只三物，对之不言心已契。","偃蹇虬龙当槛蟠，冰魂翠袖静相看。","因悲薄俗随冷煖，聊托幽芳共岁寒。","愿君终身勿相弃，岂必弹冠复联袂。","苦口虽无药石言，同心实有金兰义。","君不见纷纷轻薄流，朝作刎颈暮作仇。","人情真似翻覆手，三友贞姿宁易求。"]},{"t":"朱纪善梦草轩","f":"古风","c":["梦春草，春草满池塘，谢子空含泪，王孙几断肠。","梦春草，春草池塘满，丽日友于情，悲风死生感。","梦草转堪哀，繁霜一夕来。","凋零馀片叶，憔悴只枯荄。","他人梦草得好句，我梦草悲紫荆树。","少年梦草已伤情，老来梦草骨亦惊。","几回枕上睡初觉，残夜孤鸿不忍听。"]},{"t":"柏室","f":"七言古诗","c":["杨家住在南山侧，不种棠梨惟种柏。","棠梨开落易衰荣，柏也亭亭色镇青。","屈曲灵根蟠厚地，崔嵬钜干拂高冥。","天风乍起生竽籁，撼屋惊涛忽澎湃。","雷霆白昼走蛟鼍，云雾中宵见光怪。","良材自有神明扶，下视凡木皆庸奴。","狄门桃李敢争艳，田氏荆花差可徒。","杨郎爱之如爱宝，四季俱宜夏尤好。","赤日行天暑不知，清阴覆地凉偏早。","孔明庙前根久枯，御史台中树亦无。","何似君家书屋外，萧萧寒翠两三株。"]},{"t":"罗郎生子歌","f":"七言古诗","c":["罗郎通家良子弟，长在豪门偏意气。","衣纫藕丝绩缕轻，扇写蝇头字形细。","才华磊落识时宜，早有芳名闾里知。","不学寒酸腐儒辈，肯随浮薄市廛儿。","仗义疏财迈流俗，终年只把遗编读。","问学渊源推豫章，一脉书香要令续。","昨日惊闻忽捧珠，天上麒麟骨格殊。","美锦斓斑裁襁褓，高闳窈窕挂桑弧。","桑弧由来表奇瑞，清尊绮席犀钱会。","何人还解听啼声，先卜异时儿富贵。"]},{"t":"胡子壮游歌","f":"古风","c":["识子壮游日，才华杜樊川。","扬眉吐英槩，远泛江湖船。","江湖少俊非凡俦，青罗束带乌貂裘。","挥金买笑纵欢赏，等闲到处成淹留。","淹留从教秋复春，身轻富贵若浮云。","璚箫度曲对花听，翠被笼香和醉薰。","家声意气谁可及，喧呼剧饮争豪逸。","飞觞百罚双妖娆，岂惜缠头锦盈匹。","光阴悠悠逝水忙，忽看玄鬓点吴霜。","娇歌慢舞志终极，长揖相知归故乡。","归来旧态都忘却，貌得高情在林壑。","独行只挟琴书随，好境登临有真乐。","风流一去散如萍，天涯无复寻芳盟。","雁门学士妙文翰，挥毫莫写平生情。","平生情，良未足，九京若更逢何戡，重唱当年渭城曲。"]},{"t":"竹轩歌","f":"古风","c":["挺挺馀万竿，亭亭最耐看。","四时不改青攒攒，凤凰翎缀碧琅玕。","摇落穷冬木皆坠，丛色依然独苍翠。","节上长留六逸诗，叶底犹悬七贤佩。","时人种花媚春暄，鼓箫酣赏集华轩。","高干凌云岂解识，芳筒叶律讵曾闻。","怜生潇洒啚盈卷，笑我参差种满园。","莫谩学他桃与李，开花着子狄公门。"]},{"t":"寄定岩戒上人","f":"七言古诗","c":["钟山老禅精律戒，少小为僧今老大。","菩提非树镜非台，比却卢能更超迈。","诸缘泯绝七情空，万念消磨一性融。","涧水原同清净想，陇云浑似去来踪。","自言真能忘色相，坏帛纫衣枯竹杖。","飘如海鹤轻如萍，遍游五岳稀定向。","片月翛然物外怀，行藏不许世人猜。","布金应随长者园，持钵或赴龙宫斋。","知师无求复无着，眼前衲子那可学。","浮生若未断六根，幻躯岂得挥五浊。","我时虽见宰官身，意马心猿久已驯。","拟拨懒残煨芋火，蒲团分座话声尘。"]},{"t":"钟山樵隐歌为陈徵士致广作","f":"七言古诗","c":["金镛坠簴知何日，化作圆峰翠堪挹。","就中闻有束薪人，绝似飘飘晋王质。","行歌伐木窥云泉，遇着围棋世外仙。","倚树傍观未终局，斧柯腰下烂多年。","划然更作苏门啸，奇响铿轰生众窍。","恍疑霜夜泊枫桥，百八鲸音震岩峤。","不识人间利与名，优游胜处乐馀生。","烟霞放浪忘情久，笑杀骄妻会稽守。"]},{"t":"题王母图","f":"七言古诗","c":["御风八骏归来后，世上徒传白云调。","承华秘殿九光灯，茂陵五夜清斋候。","紫气红光烂烛天，青鸟先将消息传。","层霄顷刻阿环降，龙颜不及蛾眉鲜。","初人自与时人异，长生之术非难致。","金盘空食五枚桃，笑杀刘郎匪仙器。"]},{"t":"题董生卷","f":"古风","c":["董生行年过三八，早攻医术兼笔札。","扁仓遗绪屡探寻，晋唐妙迹频摹拓。","斗鸡走狗非尔宜，难经书法稍通知。","挥毫切胍名并驰，抄方学帖少暇时。","潜心积久镇临池，池波染墨玄凝脂。","阶前未作铁门限，圃中惟种仙灵脾。","近来小楷甚遒媚，一戈一画不容易。","韵度微窥洛神踪，规模剩得兰亭意。","杏林子弟谁如汝，四人请疗三人愈。","持笺觅剂争造庭，真行丸散欣然与。","巙学士、刘河间各专一技未是难，董生二者寔可取。","字攻药效众推许，若教更下苦功夫，便足继韩公茂并詹孟举。"]},{"t":"题周参政所藏山水小景","f":"古风","c":["天壤有异境，描摹付良工。","佳山与秀水，幻置轩窗中。","村村陌陌皆胜处，花竹园林饶雅趣。","过鸟疑飞却不飞，行人欲去何曾去。","松坡竹坞叠更重，雪瀑倒泻青芙蓉。","冈峦岛洞尽在眼，樵牧耕钓俱可容。","九曲溪流漾清泚，荒渡斜阳见舟尾。","石上吟翁镇日留，栏前眺客经年倚。","我观风物似杭州，树木云霞分外幽。","岂必西湖有奇胜，展图高兴亦悠悠。"]},{"t":"题严滩独钓图","f":"楚辞体","c":["桐江连天兮秋水长，富春摩空兮烟树苍。","客星兮寒芒，汉宫兮苔荒。","彼争攀龙鳞兮铭勋旂常，此宁着羊裘兮垂纶沧浪。","以足加腹兮忱故态之犹狂，廉贪立懦兮揭世之防。","云台钓台兮其高颉颃，二十八人兮图像已忘，先生万古兮岿祠堂。"]},{"t":"题猗兰图","f":"楚辞体","c":["莽平原兮丰茸，伤极目兮棘丛。","棘丛兮匪菅则蓬，彼美君子兮玉雪其容。","湘之水兮幽且雄，腾蛟螭兮舞虬龙。","昼黯黯兮雨溟濛，渺音尘兮何由通。","徒结郁兮寸衷，川迢遥兮路不穷。","些招魂兮托予悲，揽芳菲以佩服兮聊饰夫厥躬。","色之泛兮光风，芬之播兮谷中。","微佳人兮我谁从，思重华兮莫逢，羌独怀古兮寄丝桐。"]},{"t":"题道士陈致静栖霞亭","f":"七言古诗","c":["黄冠栖霞若栖木，朝与霞居暮霞宿。","阒无几榻只依霞，千顷霞光炫人目。","谓霞可栖仍可餐，讴吟咽嗽霞中间。","霞东煌铓上初旭，洞照肺腑如霞丹。","人疑尔真在霞上，尔托霞名聊自诳。","或疑或诳霞不知，霞尔是非皆幻妄。","嗟予久爱烟霞好，拟衣霞绡拾瑶草。","还寻钟吕蹑飞霞，同饮霞浆后天老。"]},{"t":"题秋塘鹡鸰图","f":"七言古诗","c":["秋风淅沥秋塘净，菰米沈波荷折柄。","翻藻鱼跳水气腥，采菱人散歌声定。","莲茎袅袅缀枯房，上有雍渠立晚凉。","翠盖裂残浑改色，红衣落尽尚馀香。","图中颇得周诗义，未论工拙先观意。","不写和鸣写急难，人间谁独无兄弟。","嗟我龙钟命弗齐，今年同气委黄泥。","白头徒重鸰原感，展卷他乡忍泪题。"]},{"t":"题夏良医复真卷","f":"七言古诗","c":["复真先生泯世缘，耳聪目烱发鬓玄。","熙恬淡泊得所养，元气不耗精神全。","梁园曩岁始识面，问荅喜听吴音圆。","医师谁最擅高手，只数夏氏尤攻专。","初疑傲兀态蕳抗，渐久渐觉逾恭虔。","夸毗纵恣逐物欲，妄认赝伪戕其天。","黏花缀叶厌靡丽，独尚质素操益坚。","我惭老至百念冷，但愿古道今重还。","浇漓尽除淳朴返，巧诈悉屏轻浮悛。","先生谓与已意合，屡接谈论陪周旋。","去秋遘疾势颇怠，喘息廑续加沉绵。","危如泛海驾钜浪，孰能力挽风中船。","先生制药亲为煮，服未终剂病已蠲。","体胖心广真性复，坐卧自在行轻便。","观形察色夺造化，亶有起死回生权。","梏之则夭保则寿，具载文记非虚传。","由兹致谨敢暂忽，夙夜兢惕如临渊。","方知根本在握固，解使短促翻长延。","先生颔首向我语，复真此外无馀诠。","仙方奇秘谅难学，金丹辟谷皆徒然。","何如旷怀饮美酒，曲蘖可引松椿年。","瞢腾一枕醉眠里，梦到太古羲农前。"]},{"t":"石泉茅屋歌为致仕赵尚书作","f":"古风","c":["艮岳暮云表，夷山芳草边。","河流浩荡向东注，缘树远近皆平川。","梁园空旷萃森爽，桑畦麦垄相接连。","那知城闉别有最佳处，泉甘石润殊幽偏。","是谁心赏得真趣，柴门茇舍临漪涟。","其中之人情高列仙，坐对崷崒卧听潺湲。","声疑佩环振，势若虎兕骞。","荆薪夜煮代粮糗，椰罂晓汲烹兰荃。","初平徒劳牧紫烟，此地亦复如羊眠。","或潴或泛长涓涓，绝胜庐阜千丈悬。","拾遗偪侧朴陋只数椽，岂似兹室花竹妍。","忆从垂绅正笏位八座，经济讵敢思归田。","功成挂冠抛世缘，却寻旧隐萝自牵。","一泓任教春雨涨，三重未怕秋风掀。","已欣恳玉皇案，何妨笑拍洪崖肩。","展公锦囊卷，写我瑶华篇。","拟陪杖屦弄云月，洗耳清泠闻舜弦。"]},{"t":"题夹竹桃花图","f":"古风","c":["修竹傲冬雪，崇桃媚春阳。","刚柔既殊性，艳冶宁联芳。","画工未必知物理，强写清标伴妍美。","气味原来自不同，枝柯讵肯轻相倚。","翛然凤尾静且幽，下视靡蔓皆庸流。","贞姿岂作俗花友，直节终非凡卉俦。","回首韶华易枯槁，雨折风飘委泥潦。","憔悴空怜曩日荣，妖娆宁复前时好。","此君依旧挺长竿，四季皆宜夏更寒。","万紫千红零落尽，青青还与报平安。"]},{"t":"送朱逸乐还乡","f":"七言古诗","c":["鹃啼燕乳催春色，练萼飘香不堪摘。","豳岐骏马越罗衫，汴砀游人故园客。","君家前代多簪缨，宋元诗礼留芳馨。","约山煌煌郡倅贵，架阁侃侃儒林英。","庆门积善天所祐，百年炜烨科名旧。","乘轩要路总豪雄，考槃绝涧都耆寿。","我朝泰运开隆平，阿翁屡被贤书徵。","遗荣恳辞民社寄，养晦惟结鸥鹭盟。","承传复得难兄弟，就中逸乐尤瑰异。","铜台岂惮登眺劳，梁园共诧歌词丽。","蹇予垂老临大籓，抚绥缉理稀曾闲。","薇花深署到者少，几回谈笑生欢颜。","况又相知且相契，鱼水亲情笃高谊。","数载频蒙慰藉勤，一旦宁云别离易。","君家奕世居乌江，石潭孤塔街市长。","虽无红杏照颜色，尚有青松环草堂。","鹏坊西行亦咫尺，竹林群彦多能识。","会间倘或询何如，贫是为官好消息。"]},{"t":"题白海青图","f":"七言古诗","c":["有鸟有鸟海东青，羽仪戍削心性灵。","奋身晴滚半空雪，举翮秋摩层汉星。","皇仁诞敷被冰壑，物类随应踰沧溟。","九霄振翼逐流电，千里转瞬追奔霆。","饥来那暇闯林薮，宿处正欲投岩扃。","神恬意定色鲜洁，麾之不去亦不惊。","初疑稍迫必翔翥，徐呼亟下尤安宁。","野夫耕耨岂庸此，时将奉馈亲藩庭。","王虽甚爱弗敢蓄，荐诸丹扆输忱诚。","想当胚腪潜孕秀，氤氲翕聚川原精。","阴升阳降亭毒运，铅旋汞转英华凝。","山都护巢雾气滃，木怪守树风威停。","琼丸迸裂皬然出，月光灏采同晶荧。","银河晃瀁濯奇质，玉露厌浥溥脩翎。","坚刚劲爪铁铦利，蒙茸浅毳霜轻盈。","体排疏花墨痕淡，目灿悬镜金睛明。","皂雕固当逊豪逸，苍隼孰与争凭陵。","耻擒狐兔猎梁苑，荣厕鸾鹄朝神京。","绒绦絷足锦鞲臂，韦笼冒首朱衣擎。","三司寅送拥冠盖，百骑肃导扬旃旌。","岳祇袪尘敛氛祲，渎鬼挽舫浮清泠。","在途扰驯态闲暇，入觐竦惕心屏营。","窥觇未许贵官睹，哺饲先得虞人矜。","至尊含笑锡盼顾，词臣献颂歌祥祯。","上稀游畋既罕用，尔纵猛鸷何由呈。","惟叨豢养毕微命，更辱卷轴留遗形。","老拳谩誇潏水鹘，真骨徒诧绵州鹰。","作诗纪瑞拜且祝，天子万寿王千龄。"]},{"t":"昔年谣示七郡父老","f":"古风","c":["昔年我来徵需重，尔有田园何暇种。","今年我来民差好，诸般免却无烦恼。","昔年逃夫今不追，昔年逋租今不陪。","今年频赦昔年罪，昔年流移仍抚绥。","白头父老来汝告，朝廷厚恩要补报。","便应差徭莫欠粮，休赌钱钞勿为盗。","勿为盗，休赌钱，男子务稼穑，女子治丝绵。","俗皆淳美人晏然，我亦思如召伯贤。"]},{"t":"陌上桑","f":"七言古诗","c":["曈昽晓日艳阳天，此时秦家蚕正眠。","春深桑叶嫩芊绵，罗敷采摘出城边。","东条西条相纠缠，满目淑景丽且妍。","繁红芳紫万仍千，煇煌宫锦绚晴川。","照见罗敷貌婵娟，鬓云倭堕鸦色玄。","步摇斜插钗凤偏，素姿何曾屑丹铅。","香龈皓齿疑贝编，眉横青山黛绿填。","杏脸细腻霞晕鲜，项如蝤蛴搓玉圆。","额角斜贴翠花钿，宝珰耀耳玛瑙悬。","裙拖秋水笼步莲，月钩窄小进难前。","盘囊锦带缀珠璇，同心绾结一双联。","暖风披拂飘兰荃，从傍过者惊复怜。","尽道罗敷是神仙，使君骏马来翩翩。","下马揖赠黄金钱，欲同携手共周旋。","罗敷低头久默然，逡巡微听细声传。","自陈未笄窥简篇，颇知礼训守贞坚。","闺房节操雪霜蠲，瑩比明蟾照清渊。","夫君豪侠称英贤，才兼文武寔两全。","骅骝丝辔象牙鞭，麒麟锁甲剑龙泉。","扬麾分符领兵权，雕戈画戟拥旌旃。","流苏复帐驼绒毡，博山乱喷沈水烟。","侍儿浓妆森后先，霞绡长裾舞褊褼。","左回右转何轻便，舞罢巧按鹍鸡弦。","烹羔刺豹开琼筵，蒲萄名酒满觥船。","犀箸不下饫腥膻，夫君欢娱无与肩。","罗敷嘉言皆陈宣，陈竟敛衽携筐还。","人生妃匹本定缘，使君有妻谅盛年。","丁宁疾驱归去遄，结发义重勿弃捐。"]},{"t":"题西湖景画","f":"七言古诗","c":["平生梦寐想西湖，老大才能阅画图。","绕村幽径不堪步，横渡扁舟若可呼。","天竺钟声出云里，雷峰塔影沉波底。","花间缘绮苍童抱，柳下朱阑翠鬟倚。","汀鹭联拳雪羽毛，渊鱼拨剌金鳞尾。","游人竞泛总宜船，三三两两六桥边。","细文轻绢新裁扇，浅色香罗初换绵。","回桡别自寻佳处，直向菱荷尽头去。","风蒲烟苇接连洲，露叶晴梢高下树。","曾闻此地最繁华，试访钱家与宋家。","故趾春深走麋鹿，古城秋暝啼鸱鸦。","事殊时改空陈迹，射潮有箭留砂碛。","坠井银缶许世传，渡江泥马知谁识。","葛岭妖桃照眼红，苏堤芳草伤心碧。","华堂永日玩丹青，逍遥绝似武林行。","凭君莫说杭州景，惹起登临无限情。"]},{"t":"薛将军具庆歌","f":"古风","c":["薛将军，骁且雄，鼻端出火耳生风。","身名挺特万众中，守边从征西复东。","搴旗斩级频立功，曾扫勍敌平诸戎。","倾心尽诚事太宗，振威扬武比虎熊。","腰悬秋水双芙蓉，勇字题盔明月弓。","捣虚敌坚当前锋，勋高报厚爵秩崇。","光华富贵夫妇同，十子英俊气吐虹。","定省早暮齐婉容，綵衣新染鲜且浓。","膝傍笑嬉色和雍，焚香酹酒拜上穹。","愿祝庭闱寿如嵩，福祥竞集二亲躬，共享禄养乐无穷。","蟠桃结实屡春冬，灿若旸谷晓日红。","帝令栽在王母宫，世得食者升太空。","瀛洲羽客号赤松，应能悯念将军忠。","玉手自摘丹霞封，两枚下赐媪与翁。","我闻此果不易逢，味才入口颜还童，具庆天长共始终。"]},{"t":"驺虞歌命补作","f":"七言古诗","c":["钧州有兽驯且仁，身如白虎性如麟。","雪月英华为骨格，阴阳秀淑作精神。","双瞳每讶常悬镜，四足何曾暂蹑尘。","墨缕萦肤浓染黛，霜茸剪毳巧丝银。","丝银镂璧相鲜丽，禀性慈良不搏噬。","盼顾生草忍践伤，逢着生虫恒引避。","熊貙屏息既钦服，獬犴闻风惭猛厉。","山融川结自应殊，鬼护灵呵畴敢易。","卫士窥觇敬启王，王言此物异寻常。","命披尔雅深论讨，使阅周诗细考详。","尔雅周诗同一义，名曰驺虞端的是。","皇家恩泽久涵濡，海㝢休祯聿来至。","来至爰从汴水隅，清斋晨迓即郊墟。","蔼蔼芳花映冰质，瀼瀼繁露湿文躯。","文躯寔匪蒐田得，纯忠纯孝能敷格。","虽云地产壮亲藩，忱乃天教彰圣德。","队仗戒严轩槛盛，军校舁随帐幕行。","窈窕腰间披绣芾，玲珑颔下系珠缨。","万斛楼船连夜发，千声笳鼓一时鸣。","遥辞艮岳梁园境，远贡蓬莱建邺城。","蓬莱咫尺五云间，王躬进献悦龙颜。","侧身拜舞趍跄巧，垂首盘旋气象閒。","垂首侧身仍侧耳，妥尾徐前复徐止。","夕卧香茵禁苑中，朝濯甘泉御河里。","得侍金阶兼玉墀，屡啖黄流并紫芝。","廷臣稽颡尽称庆，儒官伏阙竞陈诗。","赐出京城民快睹，老壮奔驰日旁午。","拥道争看杂女男，填街队仗喧箫鼓。","填街拥道共嗟称，穹祇荐此瑞朝廷。","底须想象空摹影，幸遇升平真见形。","共诧奇祥冠今昔，谁知宵旰存谦抑。","所重年丰所宝贤，洛龟宛马诚何益。","荡荡巍巍昌运开，熙熙皞皞似春台。","永沐周南召南化，为歌为颂愧非才。"]},{"t":"赏牡丹听琵琶歌","f":"七言古诗","c":["槽圆项细中空洞，翠索金环妥肩重。","泛商流徵断仍连，愁怨欢娱杂悲痛。","弹来弹去音和平，满座回颜带笑听。","转到天香牡丹品，玉笙宝瑟一时停。","小莺学语泉出窦，湖面跳珠飞雨骤。","两弦刚劲两弦柔，促急舒徐自先后。","谩说开元贺老名，梁园别有擅场声。","花前众乐才收响，一匹缠头锦先赏。"]},{"t":"梅隐歌为萧医士作","f":"古风","c":["曾随罗浮仙，夜访萧史台。","台前几株树，粲若琼瑶开。","粉面娉婷淡梳洗，娟娟绿萼娇相倚。","龙宫舞女白霓裳，解佩招邀明月里。","须臾晴雪洒石阑，长风不惜轻吹残。","搴芳忽遇萧史裔，幽情雅致真难攀。","笋皮裁冠纸裁帐，惟耽嘉遁无官况。","饮冰寄傲寒香中，忧患何缘到心上。","巡檐行歌贪看花，寻常每至参横斜。","轩裳梦断任身懒，山水情多从鬓华。","纵令对酒吟东阁，争似扶筇探西郭。","第能曾并济川舟，效用终惭活人药。","活人应多功已深，年年着子满高林。","阳回一气得春信，生生孰识堪舆心。","调羹事非成契阔，回思故园渺天末。","独馀酸味今尚存，谩道能除世间渴。"]},{"t":"题祖来上人罗汉图","f":"七言古诗","c":["佛法无外无中边，无起无灭无斜偏。","阎浮众生泡影然，聚散倏忽非牢坚。","业风播荡苦海掀，流转沉溺畴能援。","大雄世尊兴悯怜，慈悲为棹波心船。","拯拔群类出盖缠，伊谁奉命司化权。","三六开士相蝉联，涅槃不入住大千。","人人变幻神通全，导迷诱昧息妄缘。","白云枯木空岩前，蒲团宴坐禅宗禅。","金环杖锡树杪悬，有时罗斋入九渊。","珠宫贝阙长周旋，摩竭迎送惟擎拳。","有时松下谈真诠，猿听虎侍纷后先。","袈裟半着袒右肩，有时赤脚临奔川。","所乘之筏汀芦编，万顷径度轻翩翩。","我曾梦访石桥仙，宾头卢与论三玄。","若餐沆瀣饮醴泉，百花茶香亲手煎。","钵盂水满腾蜿蜒，觉来一室空云烟。","只今回首知几年，虚名羁绊世事牵。","也知维摩疾未痊，螺山上人绝荤膻。","持画请施罗汉篇，展图谛视峰峦巅。","十八尊内见两贤，双瞳深碧绿发鬈。","项光闪烁顶相圆，细民举首仰视天。","再拜求救苏颠连，上人戒律确且蠲。","根尘识想俱泯捐，早成正觉坐青莲。","梵释围绕龙象筵，应真此时恭执鞭。","我言岂异佛口宣，亘亿万劫长流传。"]},{"t":"祷雨中岳有应赋此以答神贶","f":"七言古诗","c":["剖开洪蒙奠清浊，汇为湖江峙为岳。","四方环列独崧尊，气压中州势磅礴。","众峰摩云排玉笋，晓翠夕霏纷错落。","储祥蕴秀产英贤，捍患禦灾司善恶。","累朝褒崇载祀典，宝幡天香照林壑。","重门秘殿俨深邃，孔盖长旂下寥廓。","怜斯县小壤田瘠，加以旱乾沟浍涸。","我斋致祷竭寸忱，讵意昭孚类期约。","飞廉霹雳咸听命，甘澍既倾炎暑却。","顿令凶荒转丰稔，复使愁忧成笑乐。","微衷曷以答神贶，跽荐溪泉羞杜若。","宇宙升平庙貌新，万古千秋镇伊洛。"]},{"t":"耕读轩","f":"七言古诗","c":["男儿志气固叵量，耻学术艺羞为商。","屈指只今踰二十，广额秀眉瞳子光。","生来本是爱闲者，乍可骑牛懒骑马。","数亩腴田手自锄，几联佳句人争写。","庸流岂能知丈夫，笑尔把耒仍读书。","古之豪杰宁苟出，富贵纵得徒区区。","且适林泉隐居乐，汉史何劳将挂角。","远垄秋风稻穗齐，短檠夜雨灯花落。","不见南阳诸葛公，油然高卧草庐中。","殷勤不有三番顾，磊落应无千载功。"]},{"t":"汉武帝将军柏歌","f":"七言古诗","c":["茂陵求仙期得仙，思骖玄龙飞上天。","密函秘检事封禅，宛马驰来崧岳前。","崧前独爱三树柏，锡以官名表殊特。","至今犹说是将军，香叶屯云凝翠色。","当时立心隘八埏，一举欲息昆崙颠。","穷兵渎武事远略，此岂解有冲升缘。","秋风辞哀萌晦早，王母桃花几回老。","金茎瑞露成清泪，珠襦玉匣埋荒草。","羡渠老寿在名山，驻龄弗藉文成丹。","诙谐获听方朔论，侍从曾识枚皋颜。","秃枝锐干如铜铁，傲雨凌霜古皮裂。","地籁朝惊万壑风，精灵夜泣三更月。","武皇不归时代迁，遗尔臃肿烟霞边。","固疑孔桧颇相妒，且喜社栎能忘年。","武侯庙废摧千丈，新甫之材闻斲丧。","若论秦皇避雨松，雨松亦是平交行。"]},{"t":"题并头牡丹图","f":"古风","c":["诚斋天潢尊，游艺妙通玄。","名花擅国色，尽向毫端传。","瑩其冰玉洁，粲若云锦鲜，朵重干不弱，蒂比葩相联。","红嫣白嫩孰可拟，二乔初嫁争芳妍。","娉婷窈窕俱有倾世貌，浅颦轻笑并立偎香肩，含情含娇深自怜。","绛杏绯桃总粗俗，掩面却走羞婵娟。","始信摹写精，笔底造化全。","能令欲拆未拆蕊，顷刻烂熳轩窗前。","抽萌固弗藉雨露，赋质政尔烦丹铅。","狂蜂窥图屡往返，痴蝶侧目频留连。","从尔四序更迭开依然，写成便带长生缘。","荣悴不许覆载专，伊谁承恩得之戚畹钱。","焚香正冠再拜，展向素壁悬。","方知运思巧，直夺真宰权，永为宝玩垂千年。"]},{"t":"题兰蕙同芳图","f":"七言古诗","c":["少年遨嬉楚山麓，兰蕙苗深密如簇。","推篷政爱江雨晴，沙觜崖根相映缘。","芒鞋苧服偶徐步，随处搴芳清兴足。","丛丛叶似剪春罗，个个花疑刻寒玉。","新茎窈窕凝嫩紫，疏蕊参差飘远馥。","燕姞曾徵梦里祥，宣尼屡操琴中曲。","于今老作汴梁客，采掇无由到空谷。","生绡忽睹精妙画，况有珠玑动盈幅。","吴兴王孙差可拟，茂苑禅僧难并躅。","狂尘旷野萧艾繁，惊见联芳开病目。","藓沿怪石傍荆棘，芣苡湘筠伴幽独。","宝之不啻径尺璧，藏以髹函惟恐渎。","龙眠底用写九歌，掩却离骚观此轴。"]},{"t":"送严良医回嘉兴迎母","f":"七言古诗","c":["先生意气凌青苍，两脸渥润双瞳光。","无心求伏思邈虎，有术解叱初平羊。","门前种橘懒种杏，橘叶坠井泉浮香。","春馀着花雪羞白，霜后结实金争黄。","嘉禾世业数谁最，公论共说先生良。","针茅屡试疗鬼诀，续柳每验回骸方。","经窥素难法岐扁，科究内外兼刘张。","徵书一日贲林薮，布衣万里觐帝乡。","庸医叹羡国医骇，妙夺造化通阴阳。","仰瞻骤近日月表，陟降不离参苓傍。","亲藩授职喜闲逸，况乃仁厚逢贤王。","怜渠契阔旷定省，代尔恳恻陈封章。","宫臣走马捧敕至，特许谒告荣非常。","时当六月政三伏，敢惮触热川途长。","到家拜庆上冢毕，鱼轩亟奉登舟航。","江湖阔深富虾蟹，嫩菱鲜藕俱堪尝。","船宽物贱固可乐，纵遇好境休徜徉。","嗟予目昏牙齿豁，富贵念冷功名忘。","但存诗魔与传癖，惟此二竖留膏肓。","愿言就君乞砭治，无使久别劳中肠。","汀洲雁下寒水落，阶除菊绽秋风凉。","河漘伫候木兰棹，垆头烂醉茱萸觞。"]},{"t":"续海棠吟奉教作","f":"七言古诗","c":["覃怀之山内谽谺，小径逗入如萦蛇。","其间海棠迨千树，屈曲枝干相交加。","清明节近蕊将放，涧壑照耀皆丹霞。","晓风夜雨恣吹洒，默无语言尤可嘉。","从春复秋迭秀悴，几度空谷悲年华。","恣态娉婷孰怜惜，讵解知尔为名花。","白头樵夫束成担，赤脚饷妇簪盈髽。","凭谁报与好事者，凌犯危险来幽遐。","竹篮带土两肩荷，数里方上移春车。","剔除莓苔细剪拂，置彼乐善东平家。","地浆滋培养根本，辘轳灌溉樊篱遮。","逡巡青回旧着叶，次第绿茁新生芽。","绮窗朝玩雾露湿，绛烛夜照星河斜。","胭脂浓染未尽吐，撩乱万点红鬖髿。","天孙织就机上锦，仙人鍊出垆中砂。","玳筵逐朝递欢赏，富贵素位非豪奢。","汝今邂逅得奇遇，名园列植蒙矜誇。","西川还有奇绝品，无由自达沦泥沙。","我因稽首问造化，如何予夺令偏差。","苍穹高远莫予答，抚图痛悼长咨嗟。"]},{"t":"续冬青行","f":"古风","c":["冬青枝，忆昔南渡升平时。","瑶阶左右两行植，信是阆苑仙宫移。","亭亭碧玉作柯干，雨雾风晴总宜玩。","朝退旌旗拂叶低，细蕊轻飘雪零乱。","岂知事变大可哀，湖山歌舞尽荒苔。","王气冰销兵气盛，玄扃不固六陵开。","六陵隧中龙凤骼，义士夜深偷拾得。","亲制衾裯裹碎琼，恭题谥号挥浓墨。","捧向幽闲僻静冈，愁云惨淡月微茫。","神灵翕歘潜呵护，竁穴深沉谨瘗藏。","复恐后人迷此处，识以常朝殿前树。","翠盖阴笼土一抔，万年枝在人亡遽。","屈指于今二百秋，盛衰暗逐水东流。","皇朝既监元朝失，青史曾如野史收。","空馀孤塔钱塘浒，白发遗民忍瞻睹。","天上威神固俨然，人间俯仰徒凄楚。","弗独欷歔叹宋亡，沧桑递阅俱堪伤。","阿瞒奸计为疑冢，身死还将智力防。","浮世宁云盖棺定，十二重瞳犹未瞑。","大招酹酒续悲歌，唐公洒泪应来听。"]},{"t":"汴城阅武歌","f":"古风","c":["南薰门外春光老，絮雪晴飘教场草。","三卫精兵点得齐，练习今朝比常早。","长竿钜旗悬将台，四面辟易行人开。","前驱虎旅骏奔走，太监乘马当街来。","逡巡过去才都督，侍郎参行辔联属。","绣衣御史并三司，冠盖低昂密相簇。","绳床列坐阅武亭，城外击鼓城中听。","周遭柳围地宽广，阵势任摆方圆形。","内分横直开长道，火炮冲天队初到。","弰尽雕弓冰作弦，通题勇字金涂帽。","急鼓争喧骑士驰，骁捷不数幽并儿。","抡鎗夺槊左右射，互骋才艺誇神奇。","一声遥听敲钲响，输者鞭笞赢者赏。","荷戈束甲捲旌旃，沿路飞尘扑归鞅。","风传?篥远近鸣，纷纭部伍各返营。","太平方信从军乐，惟请衣粮不出征。"]},{"t":"江湖清游歌","f":"古风","c":["何郎落魄非顽痴，气豪志雄才不羁。","一从束发厌雌伏，龌龊羞效东家儿。","躬耕把锄既云苦，闭门佔毕亦奚补。","浩荡大鹏希有心，四方上下如乡土。","长揖里闾亲，笑别闺中人。","拟船待明发，呼酒酾江神。","双橹齐鸣片帆挂，脱巾高眠箬篷下。","但闻佳境即停桡，客里寻常过冬夏。","屡携姑苏娃，数试宜兴茶。","琼花已枯槁，玉树空繁华。","凤台铁塔频登眺，只将乐事酬年少。","青山曾访谢公墩，綵笔留题蒋侯庙。","懒向秦淮终岁留，逡巡遥泛武昌舟。","寒波赤壁三更月，斜日黄冈万顷秋。","鹤楼鹦鹉冥搜倦，跨马着鞭仍适汴。","河岳风云豁壮怀，宋金旧迹观皆遍。","孔方通灵众所趍，那知阿堵能亡躯。","尔虽好游非利驱，颇出俗流情独殊。","都抛蝇头弃蜗角，游固可嘉居亦乐。","长歌痛饮醉复醒，慎勿闲分清与浊。","我今老矣雪鬓垂毵毵，奇胜负却穷幽探。","无缘行览惟坐谈，吟成挥毫题冰衔，愿子细读精研覃。"]},{"t":"题竹为精微陈徵士作","f":"七言古诗","c":["郭侯写竹真有名，平生少写风烟晴。","兴来只爱春雨态，毫端幻出如生成。","一竿亭亭俨中立，两竿垂垂梢叶湿。","月暗苍梧鬼魅愁，波惊渤澥蛟龙泣。","精微斋里客来稀，坐对新图静掩扉。","丁宁莫向青云挂，只恐随梭破壁飞。"]},{"t":"送葛维彰人材还乡兼寄声精微陈徵士","f":"七言古诗","c":["铜龙水乾漏声小，鱼钥金寒霜月晓。","警跸初鸣雉扇开，红云半露天人表。","布衣小臣衰朽馀，来朝乞得垂老躯。","龙钟何以展报效，但愿击壤歌康衢。","秦淮北风疾于箭，扁舟到早如乘传。","天上人归鹊预知，瓮头酒熟孙能劝。","忘机笑傲林泉间，高情长与云同閒。","时人莫讶鬓成雪，承恩两度瞻龙颜。","蹇予久作词垣客，谩写新题壮行色。","同是青原白鹭人，我独胡为归未得。","送君不尽思君情，临分忍听骊驹声。","凭将千里故人意，寄谢精微贤弟兄。"]},{"t":"题赵敬重游钱塘卷","f":"七言古诗","c":["诏南有客三十强，壮心锐欲穷远方。","辔按追风俊叱拨，舟乘破浪轻艅艎。","绝伦帽顶猫睛嵌，异样绦环玛瑙装。","资生有利随时逐，遇景无妨判醉偿。","充盈货贝倾同侣，磊落情怀超众商。","半生浙水久留恋，览胜探奇浑未倦。","楮塘芝坞幽寻数，篁岭苏堤冶游遍。","煮茶频汲白公泉，沉沙屡访钱王箭。","香罗细葛良工裁，嫩藕鲜菱老翁献。","恨无磨勒盗红绡，喜有芳华侍纨扇。","段桥西畔总宜船，万倾湖波绿浸天。","两岸高峰拥禅刹，四时妙乐沸歌弦。","保叔塔存僧已去，秦皇缆朽石犹传。","且向人间作财主，岂须世外为神仙。","莫辜汗漫江湖好，千金买笑度流年。"]},{"t":"蟠桃歌寿辛太安人八十","f":"古风","c":["吾闻蓬莱山，其上玉为宫。","蟠桃九千丈，特种瑶池东。","万年柯长翠，累䙫花始红。","夜守命列缺，昼卫驱丰霳。","仍经历劫实乃熟，烂然肤色丹朱红。","龟台阿母持啖汉武帝，此后旷世想像何曾逢。","辛侯前身疑赤松，清宵神游谒真境，拜乞拟驻慈亲容。","不学方朔偷，诚恳亦见从。","果蒙仙赐遽惊悟，起视已在高堂中。","鲜凝霞浆湛晓露，新绚云彩辉晴虹。","焚香跪擎奉母食，食之灵液流心胸。","形质肉骨都换精华融，发如黑漆颜如童。","双目烱两耳聪，徒誇延龄九还七返功。","才登八旬直至百岁寿未穷，荣膺恩命更进夫人封，后天而老乘飞龙。"]},{"t":"寿朱君立则夫妇初度","f":"七言古诗","c":["蟠桃树在瑶池东，树上之实丹砂浓。","雷霆守卫云雾封，有得食者升太空。","朱家令子学泮宫，祝亲寿考感上穹。","帝敕金母并木公，两枚下赐嘉孝恭。","清宵坠向高堂中，明晨捧献媪与翁。","味才入口肠已充，白发返黑增颜红。","耳聪目明肌肉丰，循环花甲无终穷，万八千岁方孩童。"]},{"t":"题张宪副山水","f":"古风","c":["何郎画法咸称工，层峦复嶂生笔峰。","昼阴作寒云雾密，树色凝黛岚烟浓。","千崖万壑骤雨歇，洗出重叠金芙蓉。","超腾犹奔马，奋迅若蛰龙。","忽偃遽竦森嵷巃，瑶簪琼笋杳霭磨高穹。","淋漓墨沈夺天巧，能令造化无全功。","恍惊摄提初，宇宙开洪濛。","结就仙岩之，峻琵琶之雄。","玉气夜白丹光红，参苓芷术飘香风。","留侯奕叶远孙子，卜筑讲学栖其中，每将林泉芳润咽嗽怡心胸。","辞家入仕三十载，旧隐萝径屐迹莓苔封。","地宽壤沃景寥阒，绝胜海上人罕得到蓬莱宫。","虚亭临泓细路绕，小桥横岸新流通。","箨冠苧服物外叟，寻幽览胜棹轻舫，两眼饱看船头峰。","耆山鬼谷贵溪水，秀淑代有贤才钟。","嗟予本是钓耕者，宦途浪寄浮萍踪。","老至百念都成空，惟存传癖兼诗穷，可怜触处随病翁。","宁思枣如瓜，弗羡印似斗，但愿引退休微躬。","庙堂长揖别卿相，疃畦徐步偕樵农。","体倦荫双松，神閒抚孤桐。","窗间故笈父书在，掩关坐读歌时雍。","身虽未行梦先往，浩然兴落盘洲东。","还君此轴匣琴剑，悬车不待今年冬。"]},{"t":"题严良医山水小景","f":"古风","c":["鳌簪耸沧海，芙蓉飘紫烟。","画工运思极精妙，毫端巧夺造化权。","连峰特巘各殊态，一一幻出皆天然。","恍疑嶙峋绝顶最高处，参术错落根如拳。","气凡肉重莫能即，何由飞步凌其巅。","山中之人，纫兰佩荃，濯足涧底，振衣风前。","晨兴霞疗饥，宵寝云伴眠。","遨游不入五侯宅，偃蹇只听双崖泉。","清流曲折相洄沿，种得杏成花满川。","乱红缤纷坠漪涟，鸟啼鱼跃春景妍。","是谁闲泛溪上船，尽日独玩芳树边。","岂若茅亭老叟抱膝坐，语笑简默精神全。","小奚捧杖心静专，新梳绿发双髽联。","林收雾霭寺突兀，桥横木石湍潺湲。","异哉世上有此境，便思问舍仍求田。","酌君橘叶井，洗我肠胃膻。","聊依松柏岁寒社，庶引桑榆衰暮年。"]},{"t":"题山水","f":"七言古诗","c":["壮年飘飘意气豪，羞随斥鴳飞蓬蒿。","苍梧之山洞庭水，常觅胜处闲游遨。","招邀知己二三友，谈笑每日乘轻艘。","汀蘅渚杜俱逸兴，澧兰沅芷皆离骚。","并栊船头恣吟眺，底用傲兀披宫袍。","鸥边鹜畔往仍返，下上湍濑不惮劳。","莲房旋摘鱼旋脍，满吸钜斝持霜螯。","酒酣移船林外泊，脱叶乱坠惊猿猱。","细风吹树响飒飒，迸水触石声嘈嘈。","狂歌纵饮尽放浪，清醒却少多酕醄。","于今垂老尚远宦，白首黾勉追英髦。","客窗因见画中景，恍若重泛湘江涛。"]},{"t":"赠宫监","f":"古风","c":["王门内臣白且晰，三十年龄承奉职。","绯袍胸背粲鹦桃，小带围腰玛瑙赤。","性资敏慧才俊良，眉宇秀整言安详。","爰从散地初升秩，旋蒙委任嘉忠实。","应接区分诸务繁，四序何曾有閒日。","遭逢端的是前缘，富贵荣华岂偶然。","受用人间好快活，服事世上真神仙。","仙境传闻孰能至，蓬莱祖洲此间是。","底须双翼恣飞翔，且竭寸心谨随侍。","勤劳暮暮复朝朝，靴帽衣衫颁赏饶。","豪鹰雄健常令臂，生马骁腾仍命调。","一般宫官百十辈，惟尔众中受知最。","案边不敢离须臾，黄昏月上犹未退。","金龙蜡笺新墨光，冰纨象管描春芳。","画既精奇诗丽美，叩头拜赐偏欢喜。","巧匠装潢锦与绫，一时恭玩一回惊。","洛川花卉相争媚，不信丹青笔写成。","笔写成，疑可摘，妙夺造化浑莫测。","绛罗重重包绣囊，清夜丁宁要慎防。","神物由来鬼神惜，只愁取去洞天藏。"]},{"t":"题一干三萼芍药画","f":"古风","c":["菡萏秀夏暑，芙蓉傲秋霜。","炎凉各异趣，习见皆寻常。","东风别有花富贵，孤干高擎三萼缀。","窈窕含娇却是娇，依稀似醉元非醉。","嫣然开向绣阁前，中纯雅淡傍清妍。","阴晴月露总足爱，欹侧偏正皆足怜。","鹊巢小星本诚敬，天遣灵苗示嘉应。","岂特祥钟草木蕃，行看庆衍螽斯盛。","妙哉妙笔妙通神，貌出芳容巧夺真。","颜色长鲜态长好，珍图宝算共千春。"]},{"t":"松菊堂为祝参议作","f":"七言古诗","c":["铅山山间紫溪边，违松别菊几十年。","只今解组赋归去，载寻二物同周旋。","从教藓蔓荒三径，乔木芳苗尚繁盛。","盘桓树底仰高标，傲睨轩中谐逸兴。","平生于尔颇有情，寓目便觉襟怀清。","根跑茯苓斸雪块，蕊茁蓓蕾攒金英。","俗尘到少柴门闭，密叶屯云花绕砌。","翠耸端宜太白巢，黄舒最适渊明意。","非徒抚玩忧暂忘，更怜也解凌冰霜。","梦回半夜生秋籁，节过重阳馀晚香。","朝观夕对当窗牖，心交弗渝还耐久。","懒伴孤山处士梅，惟依彭泽先生柳。","钜干低丛总足怡，时飘苍雪坠东篱。","抡材不愿为梁栋，介寿何妨泛酒卮。"]},{"t":"著存堂歌效乐天体","f":"古风","c":["冯公子，身是仪宾福如此。","福如此，厚人罕俦，只叹二亲成土丘。","成土丘，频闻风木徒凄恻，重茵列鼎真谩荣，调膳称觞难再得。","忆昔金闺中雀屏，高堂具庆喜康宁。","侍宴长思绩怀橘，朝回犹学鲤趋庭。","玄宫一閟经年岁，想像痛心几挥泪。","升堂俨似觌形容，入门宛讶瞻冠帨。","升堂入门皆见之，浑疑身在膝边时。","白头尚展遗编授，素手仍将慈线持。","授书持线如当日，谛观依旧惟空室。","入梦精神或可期，终天恋慕何由毕。","愁听夜啼返哺乌，雌雄不逮竟先殂。","念尔微禽有至性，嗟哉感此涕盈裾。","感此奚须徒自苦，但应蠲洁奉蒸尝，一祭一回真若睹。"]},{"t":"传奇美人才貌歌","f":"七言古诗","c":["俊仪美女名灵芝，绿云为鬓冰为肌。","心聪手巧性温婉，喜嗔语默皆相宜。","芙蓉娉婷海棠艳，百媚千娇一身占。","非但天生绝世姿，填词和曲尤华赡。","或吹或拍或弹弦，般般自小都学全。","臂系红绡入彤邸，应知命合夙因缘。","牡丹作花三月半，日日教来花侧畔。","金缕悠扬敛笑讴，霓裳转折低鬟按。","侍奉追陪不暂离，逡巡又及暮秋时。","安排闹热浓妆扮，演习新鲜妙传奇。","府里偏矜重九节，赏菊芳筵早铺设。","淡扫蛾眉捧玉觞，一时粉黛空罗列。","二八年龄欢乐多，好风好景酒消磨。","中和亭上清平调，会耍庵前宛转歌。","通音晓律谙文墨，纳令联麻俱解得。","珍翰过蒙赐咏篇，香纨更荷图颜色。","莲步轻移拜案傍，气飘兰麝启莺吭。","宠恩隆厚何由报，惟祝绵延宝算长。","崔徽徒闻擅才艺，枉写形容缄恨寄。","光荣讵敢比灵芝，佳章佳画褒佳丽。"]},{"t":"题雪梅倚竹图","f":"七言古诗","c":["旬宣曾过罗浮洞，万里丛深驻吟鞚。","冯夷剪水为飞霙，脩篁叶冷擎偏重。","撒盐飘絮纷轻盈，六出五出俱鲜明。","空中树上两争白，月下风前都赛清。","乾坤一色纤尘绝，雪喜遇花花喜雪。","险径虽平少客行，繁枝纵好无人折。","冰姿绰约真自怜，高情只倚苍筤边。","先开后落得春早，易积难晞因地偏。","忆从移节临他壤，良夜几回劳梦想。","世间奇绝在遐陬，广平去后知谁赏。","老眼观图重叹嗟，旧游迢递隔天涯。","琼葩绿萼应如昨，惟笑衰翁双鬓华。"]},{"t":"题东坡游赤壁图","f":"七言古诗","c":["东坡先生人中龙，才高屡被群小攻。","遭谗近谪齐安东，渔樵混迹忘显融。","岂以得丧留心胸，吊古惟访前代踪。","两游赤壁当秋冬，扁舟泛泛波溶溶。","东山月出来清风，举酒属客谈从容。","缅怀公瑾真英雄，破敌于此成奇功。","老瞒胆落摧兵锋，烟尘涨天烈火红。","楼橹灰灭须臾中，故垒回首生蒿蓬。","运去物改世不同，沉沙遗戟埋榛丛。","临流但见双崖穹，崖根下俯冯夷宫。","滔滔江汉仍朝宗，孙曹意气宁重逢。","千年往事付画工，兴亡割据俱已空，惟有两赋传无穷。"]},{"t":"题鸂?图为陈则裕赋","f":"古风","c":["绿筠低映桃花红，金沙滩暖波溶溶。","一双鸂?好毛羽，相依相顾雌随雄。","却怜鹦鹉与鸲鹆，锁闭樊笼伤局促。","饮啄虽云豢养丰，何如自在林间宿。","缡褷锦翼文采新，照影且在清溪滨。","丁宁莫去春江上，江上鸳鸯妒杀人。"]},{"t":"题梅图","f":"七言古诗","c":["补之华光本同调，王冕专门独臻妙。","当时叔雅亦知名，瑰奇总让吴兴赵。","吴兴兄弟宋王孙，玉雪为骨冰为魂。","只将翰墨自游戏，持缣请者空纷纭。","此图先辨是谁画，不写霜晨写寒夜。","片月疑明又未明，残英欲谢何曾谢。","仙郎风度真独雄，乾坤气象蟠心胸。","花开不用雪中探，坐对琼姿幽兴浓。"]},{"t":"葵轩","f":"七言古诗","c":["春光阑珊群卉空，别有佳植开庭中。","堪怜朵朵知向日，晨瞻夕仰随西东。","从根著叶庇炎景，逐节茁蕊承薰风。","苞迎朝旭盏欹侧，萼媚夕照杯玲珑。","大哉化工运亭毒，胚腪秀淑归芳丛。","名虽不离庶草类，性却解与纯臣同。","种之固已寓微意，人心亦似倾阳恭。","非徒玩物实自励，亲当致孝君当忠。","一身两尽家国事，且复托此明深衷。","为询世上簪绂者，若个看花无愧容。"]},{"t":"题张佥宪琦公馀行乐卷","f":"七言古诗","c":["河东壤土邻河南，太行峻拔仍尖巉。","雄藩富盛说全晋，放勋万古遗风覃。","枣榆连林晚卧犊，桑柘绕屋春供蚕。","素敦勤俭戒奢靡，□□□□邹与郯。","苗薅荑稗禾覆陇，塾列衿佩书盈函。","乾坤秀淑罕钟物，产士磊落皆奇男。","张侯挺生古并郡，蚤擅才学青于蓝。","曩为御史跨骢马，名山到处曾游探。","晴云出岫不作雨，湿翠飘空都是岚。","前年秩满拜特命，持宪江右袪贪婪。","田间鳏茕失愁叹，庐左桀黠增忧惭。","发奸擿伏振纲纪，明比皎月澄寒潭。","公馀问俗闲出郭，屏退轩盖穿松楠。","携琴奚奴俊堪爱，髻绾两髽馀发毵。","豺狼望见惊破胆，遁迹远去藏深岩。","喧啁鼓笛野翁社，杂乱语话村农谈。","民情习俗总询遍，老鹤昂首迎归骖。","柏庭稚子候门久，喜笑竞走牵衣衫。","吾知侯心自有乐，惟许点也真非凡。","咄哉画手岂解此，我亦愧吐辞喃喃。"]},{"t":"听鹤轩","f":"古风","c":["皋禽清唳清无比，不入寻常俗流耳。","虚窗夜读浮丘经，展卷乍闻必为喜。","一声两声落层霄，石头迸裂空山椒。","三声四声风满林，邃岩幽壑留遗音。","梦醒松巢忽飞起，玄袂生寒露如洗。","引吭再作五六声，冰拆崖崩月明里。","美哉雅怀，逍遥两间，即物穷理，遗荣尚閒。","所以惟爱戛然仙骥之长鸣，聆之弗厌危坐到更阑，绝胜琴操写入徽弦弹。"]},{"t":"周孟琏六十寿诗","f":"七言古诗","c":["琏翁逍遥静养恬，长身玉立仍脩髯。","平生雅好在泉石，标格洒落心清廉。","优閒惟许一人独，荣进却让诸郎兼。","鸠形刻杖圆类铁，鹤翎制氅轻于缣。","世上功名久无梦，但遇佳境频留淹。","追随老鹿最驯扰，见者疑是白玉蟾。","风杉雪桧阴蔽日，满袖翠湿晴岚沾。","笑渠营营行路子，赤脚抗走徒趋炎。","岁周花甲值初度，画手戏取宣毫拈。","逡巡忽见寿者相，惊骇贺客争观瞻。","椿龄桂算各三百，不须更问君平占。","看教弱水十回浅，海屋方把筹重添。"]},{"t":"题石廉使所藏墨梅","f":"古风","c":["飞雪送臈尽，孤根得春先。","如何一图里，见此双清妍。","冰资玉质神仙格，谁运天机描貌得。","冉冉寒香似可闻，疏疏冷蕊疑堪摘。","封柯积干冻未消，五出六出皆琼瑶。","傍开正吐总绝似，历岁经时浑不凋。","何用巡檐索花笑，横幅高悬恣瞻眺。","酷好原欣节操同，深藏颇惜临摹妙。","道傍人暍困尘埃，画就终非疗渴材。","别有真梅着佳实，明年调鼎待公来。"]},{"t":"题会乩邓宗经先生颐老庄","f":"七言古诗","c":["灊郊亩亩皆稻田，大畦小疃相接连。","先生豫为休退计，剩买百亩荒城边。","仍将数亩搆书屋，扁以颐老争誇传。","罢官拂袖便居此，肮脏肯受虚名缠。","桃冠芒鞋紫竹杖，手版纳却轩车悬。","青衿问奇定载酒，白足结社非逃禅。","宁甘食力事耕耨，敢厌诲人抛简编。","乘闲偶出值野叟，稼穑话久因忘还。","向晚归家窗户暝，酒浆旋设灯初燃。","芹羹炊香杂薯芋，絮被卧暖兼缯绵。","方知随处有佳境，奚必镜水稽山妍。","亲朋凋零故乡远，兹地卜筑应前缘。","相期与君慎终始，恐是晚节稀能全。","叩门昏夜得富贵，吁嗟有若乞丐然。","但当益励固穷志，居易俟命从华颠。"]},{"t":"美人蹴圆图","f":"古风","c":["暑退凉初生，秋容净如洗。","娉婷事蹋鞠，笑出深闺里。","蹋鞠风流堪适情，锦瑟瑶笙教暂停。","逡巡亸袖侧肩立，低昂进退都分明。","岂无落花泛流水，亦有白打分输赢。","龙儿摆尾原曾学，凤子摇头旧已精。","两娃娇并银盘面，傍观手弄鲛绡扇。","三娃正蹴小官场，汗湿酥胸浑未倦。","圆社从来非等閒，作家取巧凭双弯。","眼亲步活转移速，解数般般谁道难。","雕阑十二相缭绕，日下芙蓉犹未了。","发乱青丝宝髻偏，尘生罗袜金莲小。","秀色诚可悦，清时慎勿辜。","桂枝香满榴结子，繁华况在神仙都。","冰纨何用空描写，别有人间真画图。"]},{"t":"富溪八景富 其一","f":"古风","c":["溪八景，何瑰奇，王家住此知几时。","自从开辟巧排列，每一出门皆见之。","南山雨馀翠葱茜，黛髻烟鬟照人面。","万斛凝岚结昼阴，千寻悬瀑垂晴练。","西符耸拔如争雄，落日倒挂金盆红。","参差树影互摇动，倏忽暝色深遮笼。","澄潭浸月凉波瑩，恍似姮娥对妆镜。","骊颔珠辉似可扪，鲛机杼响疑堪听。","层巅怪石屹不欹，上有云气长相依。","晨霞迎旭或为伴，晓雾飘空仍共飞。","三峰五岭多佳态，松颤狂飙乍澎湃。","旁礡氤氲毓俊才，鏦铮萧飒生灵籁。","文江暖泛绿半篙，潜通墨沼添波涛。","游鱼喜化金鳞鬣，浴鹭嫌缁雪羽毛。","闲居已喜专幽处，况乃周遭皆雅趣。","翰苑名公为著文，经筵大老能留句。","先庐亦在折桂乡，白头未得还耕桑。","题诗谩重季鹰感，鲈鲙秋风归兴长。"]},{"t":"富溪八景富 其二 题性灵空卷","f":"七言古诗","c":["灵师妙年慧且聪，秀眉绀顶冰雪容。","僰山滇水历几重，禀法京刹春又冬。","有大开士幻觉公，出世弘振临济宗。","千□楚楚皆象龙，钳锤恶辣加磨砻。","灵也上首才调丰，孤云野鹤少定踪。","游方翩然西复东，笠裁笋皮鞋织棕。","石头路滑莓苔封，三衣湿透秋露浓。","行住坐卧伊谁同，笑携明月邀清风。","宝坊到处多留踪，尊宿乍见惊罕逢。","不发言句藏机锋，蓦地一喝双耳聋。","恍若刮翳开昏矇，精进幢竖高崇崇。","声闻顿悟性地融，安稳自在超凡庸。","蒲团谩说禅定功，输尔根器僧中雄。","我惭白发成衰慵，颇似示疾维摩翁。","勤勤问讯劳过从，无座无饭文室空。","逡巡告别还旧峰，聊为说偈明深衷，天涯目送南飞鸿。"]},{"t":"富溪八景富 其三 题山水小景","f":"古风","c":["良工写幽景，运思颇不凡。","高崖挂悬瀑，迥野生轻岚。","林昏日欲坠，天暝云初覃。","远岸少去舫，长途乏来骖。","摩挲老眼着意看，彷佛还似湖湘南。","忆曾之官屡经此，孤舟晚泊浯溪潭。","叶凋老树曲偃蹇，泉触乱石森巉岩。","众禽归飞宿且食，雄鸣雌应相喃喃。","平沙钜迹虎新过，浅濑纤鳞鸥竞衔。","荒村无人但猿鸟，古峤有树皆枫楠。","空青冥濛翳岛屿，湿翠杳霭沾衣衫。","谁藏一匣在绝壁，云是诸葛兵书函。","雨催风撼只如故，欲堕未堕何由探。","山川奇胜怪仍险，况我爱玩性所耽。","低回但恨弗学画，辜负佳境心徒惭。","每逢好事辄为说，恍若亲睹非虚谈。","于今衰老返耕钓，鬅鬙两鬓霜毵毵。","观图忽起旧游想，浩然清兴莫可缄。","题诗卷轴坐叹息，中宵梦逐沧江帆。"]},{"t":"富溪八景富 其四 题孟浩然踏雪寻梅图","f":"七言古诗","c":["浩然先生生盛唐，锦心秀口冰肝肠。","词追风雅谐宫商，清如环佩锵珩璜。","幼邻摩诘相颉颃，子美太白参翱翔。","私入禁署逢明皇，诵诗却诵南山章。","忤意拂袖还襄阳，嬉游只在云水乡。","闲身到处频徜徉，溪山晏岁梅吐香。","跨蹇独出寻孤芳，六花乱落纷悠扬。","老树翯翯虬龙骧，痴童前引冻欲僵。","回顾似促归去忙，鹿门尚有十里强。","先生驴背寒都忘，吟哦未觉天昏黄。","开元治世文运昌，同时诸子皆俊良。","惟公制作尤擅场，篇篇首首兴趣长。","字字句句金玉相，明珠白璧争焜煌，千载不朽垂休光。"]},{"t":"富溪八景富 其五 题贰守费翎毛图","f":"七言古诗","c":["紫髯别驾才气雄，好诗好画明且公。","何人运思写动植，却使造化无全功。","琅玕欹斜竹交翠，锦绮烂熳桃争红。","联翩羽族竞来集，机忘意适雌兼雄。","不闻清香哢啁唽，惟见细毳纷蒙茸。","疾归奋翅斗轻快，闲宿敛翮俱从容。","艳葩可折禽可笼，韶光都在图画中。","飞鸣宿食总人力，荣悴开落非天工。","方知世上有好手，笔端所至生春风。","谛观此景似何处，高峰南北湖西东。","买花载酒听啼鸟，老矣未得来相从。"]},{"t":"富溪八景富 其六 悦亲行","f":"七言古诗","c":["杨家矍铄双翁媪，平生快活无烦恼。","中男颇解尽欢娱，拜跪膝边颜色好。","开封百物价直低，寻常剩有豚与鸡。","鲜鳞嫩菜好柿栗，贩来都聚隅头西。","买归为具罗盘饤，药室香凝春昼静。","满斟政喜瓮方深，迭劝岂愁瓶屡罄。","况逢禾麦丰登年，饭炊稻米衣装绵。","颐老惟知足嬉笑，安居但愿忘忧煎。","随缘供养竭医赀，且乐清贫慎勿辞。","不见巷南富豪子，祸罪贻亲异乡死。"]},{"t":"富溪八景富 其七 赠某将军","f":"古风","c":["少日随飞龙，风云际良会。","方今脩文治，父子功勋遂。","惟说先君骁且雄，雁翎长刀角胎弓。","单车直驱沙漠外，片帆径渡沧溟东。","东征西讨无不预，肯令敌骑留遗踪。","马鞍压雪耀金甲，羽箭流星贯敌胸。","小河鏖战河流赤，将军身命那敢惜。","一死博得千年名，象贤有儿承父职。","皇家褒忠恩礼殊，貔貅坐拥专城居。","将门出将传奕叶，此语由来诚匪虚。","重圭叠组争照耀，韬钤更冀曾玄绍。","闲暇投壶复雅歌，高情祭老堪同调。","莫匣三尺剑，还磨丈二矛。","将军壮气死不休，吾知燕颔当封侯。","他时倘建凌烟阁，画像期公登上头。"]},{"t":"富溪八景富 其八 再赠","f":"七言古诗","c":["下邳壮节伊谁如，谈兵早读孙吴书。","夜庐母冢辄流血，晓陷敌阵随捐躯。","西江都帅誇贤子，为子为臣亦如此。","承欢敌忾嗣前人，岂直相传袭金紫。","大廷宠赠祖父功，明威昭勇官资崇。","碑烦史笔制词美，诰锡奎章题字浓。","怙恃九原嗟不作，想像音容空泪落。","致养无由奉笋鲑，竭诚但愿倾葵藿。","裨校同推智略深，亲恩国事两关心。","吾知燕颔封侯相，汉代将军重见今。"]},{"t":"题梅","f":"七言古诗","c":["吴山绕舍栽奇卉，几树凌寒绽繁蕊。","同云黯黯天茫茫，朝来素萼添粉妆。","缤纷六出乱飞舞，似与五出争妍芳。","水边沙际失疏影，野外风前飘暗香。","徐君想是罗浮客，惯貌花容染花色。","酒酣兴适弗自珍，贵士幽人皆觅得。","兹图所写尤精神，正开侧吐俱逼真。","冰肌清瘦最耐冷，玉质轻盈不受尘。","费侯吾知聊托意，展玩追怀旧游地。","遥忆逋仙莫可招，虽逢驿使那堪寄。","眼中画手多凡庸，八十之年老更工。","岂必西湖船里看，闲斋坐对胜推篷。"]},{"t":"题南溪萧氏山水小景","f":"古风","c":["西昌有士生名宗，孤高格调冰雪容。","性惟爱山复爱画，画里坐对青芙蓉。","乍观尺素杳难辨，野色川气相溟濛。","初疑为巫峡，列此十二峰，雨馀轻黛增鲜浓。","阳台神女彷佛精灵通，楚襄之梦恍惚当谁穷。","沐猿涧鹿悄无迹，千岩万壑烟霏笼。","又疑是匡庐五老排层穹，乃在彭蠡之北、盆江之东。","凉影倒浸波溶溶，飞英乱舞垂萝风。","吾家翰苑老供奉，揽秀绝顶巢云松。","锦袍骑鲸乘月径返蓬莱宫，开元诸子莫追逐。","吐句尽如仙语真，孤雄仍闻夙昔读。","书处氤氲竟日丹，霞封胡君特来索。","我赋笑迎起抑揩，昏瞳便令挂壁着。","意看其间景象既弗类，运思落笔俱凡庸。","僧繇久逝范宽没，海岳亦往庵居空。","南溪别有奇绝地，春深绿与耶溪同。","杰构隐映苍桧中，二三好客劳过从，酒醅旋压黄粱舂。","幽非桃花源，邃异子午谷，土美俗朴堪耕农。","罕曾袖刺谒时贵，屡尝含哺歌年丰。","我欲携焦桐，飘然谢尘踪。","汲泉采蕨疗饥渴，净扫白石弹秋鸿。","如何病兀絷双足，谩令清兴蟠心胸。","挥毫写罢付君去，殷勤寄示兰陵翁。"]},{"t":"题吴山书舍","f":"七言古诗","c":["虎林胜槩闻天下，城外城中总堪画。","一峰最近是吴山，传道渠家好台榭。","其间非藏玉与珠，剩有万卷牙签储。","短檠静夜乐讽咏，小轩永日忘饥劬。","寸阴那肯轻抛掷，及此少年勤致力。","无暇岂窥董子园，不贫宁凿匡衡壁。","逢疑必辨理必穷，务使曲畅仍旁通。","知行兼该造成德，到此始克收全功。","古杭人物冠江浙，况乃才华迈同列。","五策风檐历历陈，一枝月桂高高折。","守令为坊立宅边，新题钜扁笔如椽。","比邻多少连居者，若个生男似尔贤。"]},{"t":"题雪窗兰为济润上人","f":"七言古诗","c":["雪窗前元住虎丘，清致彷佛支远流。","解将翰墨作游戏，写成兰石人争求。","露花风叶含生色，楚畹移来屏几侧。","乍见频看若可纫，初开半吐疑堪摘。","润师戒行如秋霜，蒲团趺坐十笏房。","根尘识想已云泯，色香声味都宜忘。","兹图谩尔时时对，外物岂能为已累。","毕竟阎浮世界空，直须悟逗真三昧。","寒灰心地槁木形，妄缘幻质难缠萦。","无兰无石亦无画，此是菩提最上乘。"]},{"t":"送刘教谕裔关西考试采玉之行","f":"古风","c":["往年采玉于阗东，今年采玉昆山中。","近来苦难得白璧，荆珉燕石常相逢。","世无明眼非无玉，水苍玄英委空谷。","何限瑰奇不见知，岂独骊珠混鱼目。","君不见琥璜在璞未琢磨，云谁识之古卞和。"]},{"t":"登天华观","f":"五言律诗","c":["玉洞开仙馆，丹梯轶世氛。","天书馀鸟篆，云笈护龙文。","灵境萧台近，空歌下界闻。","俗人如可避，不必问桃源。"]},{"t":"春日山中寻泉","f":"五言律诗","c":["春泉试独寻，度壑复穿林。","忽见流红远，方知入翠深。","色浑因悟雨，声淡只宜琴。","盥弄忘归去，穷源空有心。"]},{"t":"拟唐塞下曲九首 其一","f":"五言律诗","c":["沙尘涨北天，卫霍出居延。","苦雾埋沙碛，穷荒乏水泉。","战酣鼙鼓壮，戍久铁衣穿。","试上长城望，中原若个边。"]},{"t":"拟唐塞下曲九首 其二","f":"五言律诗","c":["羽箭雁翎刀，风沙北地豪。","弓开关月满，雕没阵云高。","劲骑三边出，匈奴一夕逃。","将军方得意，新拜玺书褒。"]},{"t":"拟唐塞下曲九首 其四","f":"五言律诗","c":["十五去防秋，于今已白头。","一身犹是卒，诸将久封侯。","部伍嫌羸病，亲知识壮游。","寒灯孤戍里，挥泪看吴钩。"]},{"t":"拟唐塞下曲九首 其五","f":"五言律诗","c":["久在边城里，风霜不可论。","六亲皆骨朽，百战偶身存。","烽燧连天暗，沙尘惮日昏。","征人家万里，谁吊国殇魂。"]},{"t":"拟唐塞下曲九首 其六","f":"五言律诗","c":["犬戎窥近塞，羽檄发精兵。","不识沙场苦，焉知性命轻。","饥鹰投古垒，疲卒卧空营。","日暮辕门里，愁听鼓角声。"]},{"t":"拟唐塞下曲九首 其七","f":"五言律诗","c":["塞马啸悲风，旌旗惨澹中。","卫青持左钺，李广在前锋。","壮士俱亡命，朝廷重论功。","将军承宠诏，天子锡新封。"]},{"t":"拟唐塞下曲九首 其八","f":"五言律诗","c":["秋霜剑在腰，曾事霍嫖姚。","诸将威无敌，全军气不骄。","弓鸣惊过雁，炮响走栖貂。","敢惮穷边苦，天家雨露饶。"]},{"t":"拟唐塞下曲九首 其九","f":"五言律诗","c":["大漠阴山外，霜天气候殊。","阴沙明远燐，寒日惨穷庐。","北阙无来使，中原少得书。","凯歌今未奏，壮士誓捐躯。"]},{"t":"病起遣兴","f":"五言律诗","c":["羸弱怯衣单，徐行觉尚难。","平和欣脉复，疏懒喜身閒。","古砚从教洗，孤琴久未弹。","朝衣如可解，归去卧秋山。"]},{"t":"送人南归四首 其二","f":"五言律诗","c":["百年同旅寓，大半在殊方。","白发羞明镜，青山问故乡。","落霞秋水阔，新雁暮天长。","安得随君往，溪南访草堂。"]},{"t":"送人南归四首 其三","f":"五言律诗","c":["候馆停杯处，扁舟欲发时。","归帆投远浦，斜日隐层陴。","暑退秋来早，潮生月上迟。","经行逢胜槩，都付酒兼诗。"]},{"t":"夜坐彭赞礼竹坞二首 其一","f":"五言律诗","c":["独坐依修竹，秋声近户多。","疏钟清紫禁，凉露湿银河。","野饭思薇蕨，儒衣想芟荷。","小山招隐意，丛桂有遗歌。"]},{"t":"夜坐彭赞礼竹坞二首 其二","f":"五言律诗","c":["静夜凉风动，林疏宿鸟惊。","玉绳低万户，银汉转三更。","露重絺衣薄，香浮茗碗清。","班姬纨扇曲，此际最关情。"]},{"t":"送沈太守之云南","f":"五言律诗","c":["滇阳南望迥，五马引双旌。","鸟道云边断，猿声月下清。","黔江通远海，僰树拥孤城。","已是诸侯贵，毋论万里行。"]},{"t":"送谢明府之桃源","f":"五言律诗","c":["楚地佳山水，桃源境更幽。","汀兰行处采，湘水抱村流。","门掩山城暮，蝉鸣驿树秋。","昔人遗洞在，骑马一来游。"]},{"t":"红叶","f":"五言律诗","c":["染树初凝茜，连林渐积丹。","露丛消黛色，霜片妒朱颜。","菊避重阳艳，花羞二月殷。","娥眉争拾取，题字寄人间。"]},{"t":"送周编修侄还文江","f":"五言律诗","c":["落景照离筵，华音促别弦。","老亲长日念，游子几时还。","玉雪中郎贵，青春小阮贤。","重来拾瑶草，迟尔五云边。"]},{"t":"送王佥事之湖广","f":"五言律诗","c":["江汉维南纪，星辰近太微。","地分方岳重，官到宪台稀。","远水连秋阔，轻帆彻夜飞。","人生骢马贵，好是绣为衣。"]},{"t":"寄刘三髦五首 其一","f":"五言律诗","c":["刘子穷经处，柴门野水滨。","俗人那可到，往哲自相亲。","道在宁论命，家空不叹贫。","幽栖如可遂，迟子结南邻。"]},{"t":"寄刘三髦五首 其二","f":"五言律诗","c":["吾爱刘公子，浑如汉士风。","古心真自得，高操更谁同。","绿水溪边舫，朱弦膝上桐。","我惭簪组累，不得远相从。"]},{"t":"寄刘三髦五首 其三","f":"五言律诗","c":["濯足清潭里，移家碧涧边。","非关傲轩冕，自是爱林泉。","野鹤閒同往，溪云静与还。","东山谢安石，何日起高眠。"]},{"t":"寄刘三髦五首 其四","f":"五言律诗","c":["才俊青云早，嗟君独出迟。","宁甘身未达，不与世相知。","霜月邻僧磬，凉风野客棋。","怀人在天末，无地写幽思。"]},{"t":"寄刘三髦五首 其五","f":"五言律诗","c":["剡书多日下，犹卧碧山隈。","只叹相如病，空淹贾谊才。","窗虚云自宿，门掩鹤初回。","好在禾川上，应愁驿骑催。"]},{"t":"题世德楼","f":"五言律诗","c":["高楼无四邻，阑槛逼秋旻。","创造怀先代，登临属后人。","水云供远眺，山月共清贫。","羡尔丘中士，云霄寄此身。"]},{"t":"送王知州赴禄劝","f":"五言律诗","c":["行尽天涯路，黔南尚几州。","孤城藏万壑，残月在扁舟。","剑阁云边断，巴江树杪流。","两回经鸟道，应记旧曾游。"]},{"t":"送梁佥事还蜀二首 其一","f":"五言律诗","c":["腊尽催行色，天涯起别愁。","暮云遮雨湿，寒水带冰流。","鸟道青骢马，乌台紫豸裘。","汉廷诸俊彦，风裁范滂优。"]},{"t":"送梁佥事还蜀二首 其二","f":"五言律诗","c":["行人冒晓霜，白简绣衣裳。","复任辞三殿，观风动一方。","秋林黄叶暗，春水碧芹香。","杜子留遗迹，烦君访草堂。"]},{"t":"送刘教谕还沛县","f":"五言律诗","c":["相望浑未远，相会竟难常。","交态贫如故，离情醉暂忘。","淮流通海近，丰树入云长。","羡尔官非贱，横经汉祖乡。"]},{"t":"送人还永丰二首 其一","f":"五言律诗","c":["迢递京华道，萧条岁晏时。","江风寒酿雪，淮水夜流澌。","远浦帆来小，残钟乌去迟。","泷冈天下重，欧子有穹碑。"]},{"t":"送人还永丰二首 其二","f":"五言律诗","c":["腊尽促归桡，离魂黯欲消。","故园频在望，知己邈难招。","灯火江村市，梅花野岸桥。","行边怜寂寞，况值雨萧萧。"]},{"t":"送邓宗经还永新训导二首 其一","f":"五言律诗","c":["相逢疑是梦，乍见总堪怜。","良会来天上，长贫在客边。","青云违故旧，华发感流年。","明发征帆去，依然各一天。"]},{"t":"送邓宗经还永新训导二首 其二","f":"五言律诗","c":["十载留京国，三年别故人。","贾生犹未达，郑老尚居贫。","灯火黉宫夕，菰蒲野水春。","谁知他域别，凄断更伤神。"]},{"t":"寄萧教谕三首 其一","f":"五言律诗","c":["见说昆山县，孤城在水乡。","汐潮通海近，云树接吴长。","夏暑圩田熟，秋阴学舍凉。","年年春色里，桃杏烂宫墙。"]},{"t":"寄萧教谕三首 其二","f":"五言律诗","c":["县斋蒲苇里，鸥鹭与相亲。","众水春环舍，孤峰晚对人。","海鲜便久客，儒服称閒身。","肯念同袍者，缄书莫厌频。"]},{"t":"寄萧教谕三首 其三","f":"五言律诗","c":["身名俱未达，朋旧故应疏。","多病惟高枕，何人慰索居。","纵鳞思旷野，疲马倦长途。","谁似儒官好，优游翰与觚。"]},{"t":"耕乐亭二首 其一","f":"五言律诗","c":["孤亭临夐野，空阔四无邻。","车马来游少，农夫就饷频。","晴檐鸠唤雨，社瓮鸟啼春。","窃禄真何补，投簪愧野人。"]},{"t":"耕乐亭二首 其二","f":"五言律诗","c":["苔痕临水润，树叶近秋稀。","细雨群农集，残阳一鸟归。","村童收滞穗，野老候空扉。","亦有躬耕意，青莎拟制衣。"]},{"t":"送人还永丰三首 其一","f":"五言律诗","c":["君家簪绂裔，群从玉连枝。","游子龙头贵，中郎燕颔姿。","双尊论久别，千里慰遐思。","六一遗风在，怀哉百世师。"]},{"t":"送人还永丰三首 其二","f":"五言律诗","c":["行李归期促，山川去路遥。","疾风狂入夜，淫雨晦连朝。","帆逐孤飞鸟，江通逆上潮。","凭将栖遁意，乡国寄渔樵。"]},{"t":"送人还永丰三首 其三","f":"五言律诗","c":["候馆促离杯，愁颜且强开。","砌蛩惊露泣，巢燕避秋回。","菊径深黄叶，衡门掩绿苔。","缅怀西汉士，据地独奇才。"]},{"t":"郊祀斋宿彭太常永年公署二首 其一","f":"五言律诗","c":["寂历容台署，高吟逸兴生。","泉香春井溢，钟断夜堂扃。","清漏随风度，流云傍月行。","暂来犹爱此，住久转忘情。"]},{"t":"郊祀斋宿彭太常永年公署二首 其二","f":"五言律诗","c":["竹静风停后，瓶香茗熟时。","灯寒人未寝，露冷鹤偏知。","颇爱良宵静，翻嫌白日迟。","年年此斋宿，载诵我将诗。"]},{"t":"太庙孟秋时享同陆员外斋宿","f":"五言律诗","c":["槐露滴新秋，斋房夜色幽。","罢琴期月上，捲幔见星流。","池冷菰蒲静，窗寒竹树稠。","清宵容易尽，香茗且淹留。"]},{"t":"碧峰寺慎公房","f":"五言律诗","c":["碧嶂屏风秀，清流束带圆。","烟霞醒醉梦，钟梵寤僧禅。","乱叶当人落，孤云引鹤还。","声闻如可契，应此息尘缘。"]},{"t":"谢赐西洋布","f":"五言律诗","c":["异缕何纤细，轻盈玉雪紑。","鲛宫初织罢，海国远输来。","捧拜荣恩赐，纫缝称体裁。","微躯增照耀，被服愧非才。"]},{"t":"竹所二首 其一","f":"五言律诗","c":["何地偏多竹，翛翛庭院幽。","夜凉难得月，雨过易成秋。","不厌贫家看，那妨好客留。","绿阴多处坐，疑泛渭川舟。"]},{"t":"竹所二首 其二","f":"五言律诗","c":["王子幽栖地，萧森修竹林。","好风催布席，疏雨罢鸣琴。","天籁醒尘梦，凉阴伴醉吟。","几竿浑不俗，赖尔悦閒心。"]},{"t":"送曹判官苏州治水二首 其一","f":"五言律诗","c":["别驾之官日，都城欲夏过。","一篷畿甸雨，双桨石湖波。","郭外青山少，城边白水多。","三吴民垫久，拯援术如何。"]},{"t":"送曹判官苏州治水二首 其二","f":"五言律诗","c":["闻道姑苏郡，东南近海潮。","圩田多夏潦，场圃减秋苗。","平易遵前训，烦苛革旧条。","更应持洁慎，玉帛此乡饶。"]},{"t":"咏蝶","f":"五言律诗","c":["栩栩戏晴光，留连媚露香。","舞随花片白，栖共柳丝黄。","树杪莺捎急，帘间扇朴忙。","南园芳草地，撩乱逐蜂狂。"]},{"t":"寓舍梅一株翳榛莽中诗以唁之","f":"五言律诗","c":["筱蔓翳颓垣，娟然玉雪痕。","寒香偏晚节，春色自名园。","鸟啄梢头蕊，苔沿砌下根。","犹能异桃李，不在狄公门。"]},{"t":"席上赠妓","f":"五言律诗","c":["绾雾纤纤指，凌波小小莲。","春山银烛下，秋水玉尊前。","舞袖鸳鸯锦，歌珠玳瑁筵。","座间俱狎客，惟属杜樊川。"]},{"t":"送陈生归吉水赤岸二首 其二","f":"五言律诗","c":["归心无日夜，孤舫不停牵。","沙蟹寒缘草，江豚暝触船。","银河通赤岸，翠壁泻红泉。","莫恋幽居好，功名贵壮年。"]},{"t":"送周布政还河南","f":"五言律诗","c":["出镇名藩重，来朝异眷隆。","残年将欲尽，知己忽相逢。","泥淖梁园雨，埃尘艮岳风。","旬宣如有暇，烦吊宋遗宫。"]},{"t":"灵谷寺","f":"五言律诗","c":["一径入青松，楼台峙化宫。","雨深山果落，云去石床空。","树老多巢鹤，潭清或见龙。","上方禅寂地，暂得寄尘踪。"]},{"t":"南溪书屋","f":"五言律诗","c":["松竹连村暗，轩窗面水清。","藓痕留屐齿，滩响杂书声。","行药因过寺，输租暂到城。","静观簪绂累，还喜布衣轻。"]},{"t":"送张巡检之云南","f":"五言律诗","c":["弓剑巡荒徼，衣冠别上林。","路经三峡险，人到百蛮深。","枸酱谙夷俗，儿童解僰音。","点苍山色古，道便一登临。"]},{"t":"送人之京","f":"五言律诗","c":["上巳风光好，新晴物色妍。","青山林下屋，绿水镜中船。","节换榆烟火，花残谷雨天。","壮游逢胜景，况觐五云边。"]},{"t":"送陈郎中重使西域十首 其一","f":"五言律诗","c":["九重辞凤阙，千骑度龙荒。","宝剑悬秋水，珠袍照雪霜。","泉源随地少，沙碛亘天长。","人羡皇华使，谁知粉署郎。"]},{"t":"送陈郎中重使西域十首 其二","f":"五言律诗","c":["天使下边州，青丝控紫骝。","风云随节旆，雨露到毡裘。","斜日羌城晚，微风塞草秋。","壮心知未已，万里快重游。"]},{"t":"送陈郎中重使西域十首 其三","f":"五言律诗","c":["逐水安营晚，鸣笳渡碛迟。","穹庐无旧馆，行卷有新诗。","骏骨天生马，奇毛地产狮。","蕃酋迎候处，一曲汉歌词。"]},{"t":"送陈郎中重使西域十首 其四","f":"五言律诗","c":["叠鼓杂鸣笳，天风送使槎。","内臣金镂带，壮士铁为檛。","去路缘青海，行营驻白沙。","单于争慕义，不用李轻车。"]},{"t":"送陈郎中重使西域十首 其五","f":"五言律诗","c":["骊马紫金环，行行出玉关。","悬河三寸舌，积雪万重山。","旗影连云卷，弓弦向月弯。","封侯儒者事，天子待君还。"]},{"t":"送陈郎中重使西域十首 其六","f":"五言律诗","c":["大漠连川远，行人去国遥。","乌孙遗种在，狼望旧名消。","夜雪戎王帐，秋风使者轺。","悬知专对好，谈笑款天骄。"]},{"t":"送陈郎中重使西域十首 其八","f":"五言律诗","c":["地势三城远，河源二水分。","火山稀好雨，盐泽足寒云。","雕没平沙外，驼鸣古涧濆。","凭高时引睇，何处是中原。"]},{"t":"送李生还安城","f":"五言律诗","c":["北蓟辞严父，南京别故人。","一身勤远道，千里念慈亲。","柳暗江城晓，萍香野岸春。","灯花先报喜，应更倚门频。"]},{"t":"南京送高教授赴选 其一","f":"五言律诗","c":["卿家本同郡，客路又离群。","夜柝敲寒月，霜钟度暝云。","征袍迷草色，古屿带潮痕。","寥落分携处，秋鸿不可闻。"]},{"t":"南京送高教授赴选 其二","f":"五言律诗","c":["共是浮萍迹，偏怜鬓易新。","江湖留滞久，朋旧别离频。","试数中朝士，应多故里亲。","莫嫌毡独冷，年纪政青春。"]},{"t":"鹭渚轻鸥","f":"五言律诗","c":["芳洲白鹭名，无数白鸥轻。","暖戏桃花水，晴依柳絮萍。","飞来兼早雁，散去避秋鹰。","何处忘机客，时于此濯缨。"]},{"t":"寄刘孟熙隐者","f":"五言律诗","c":["嵓壑幽栖者，閒情老不衰。","露葵缘客折，晚稻约僧炊。","苔径林风扫，松窗岭月窥。","诗名兼逸兴，湖海万人推。"]},{"t":"次衡州","f":"五言律诗","c":["征棹舣衡阳，孤城堞雉荒。","流云时翳日，微雨暝生凉。","江阔鸥波远，天空雁字长。","采蘋无限兴，烟水晚苍茫。"]},{"t":"己亥房山除夕营中作 其一","f":"五言律诗","c":["残腊中宵尽，孤怀百感深。","已惭先哲训，徒抱古人心。","偃息何由得，勤劳敢不任。","寒灯照空榻，拥褐谩愁吟。"]},{"t":"己亥房山除夕营中作 其二","f":"五言律诗","c":["患难仍连岁，蹉跎独此身。","风尘双短鬓，宇宙一穷人。","向曙繁星没，凝寒积雪新。","椒花今夕酒，谁寿白头亲。"]},{"t":"己亥房山除夕营中作 其三","f":"五言律诗","c":["稚子捐深爱，酸辛痛莫支。","坐愁侵骨髓，行乐负心期。","风俗殊方异，人情近老悲。","前程驽马足，敢不慎驱驰。"]},{"t":"己亥房山除夕营中作 其四","f":"五言律诗","c":["风雪当除夕，空营一榻孤。","天涯悲舐犊，地下忆童乌。","宁复衰颜壮，惟应泪眼枯。","大灵如不妄，再拜谢玄夫。"]},{"t":"己亥房山除夕营中作 其五","f":"五言律诗","c":["今夕犹常夕，如何倍忆家。","二三千里道，四十五年华。","贫有文章在，官无品秩加。","遥知妻共女，愁坐卜灯花。"]},{"t":"己亥房山除夕营中作 其六","f":"五言律诗","c":["警柝严巡逻，寒更独坐听。","凄其孤影瘦，邪许万声停。","败壁风穿苇，空庖凌在瓶。","茫茫天壤内，么么一螟蛉。"]},{"t":"五峰庵住上人房","f":"五言律诗","c":["住公栖遁处，重到只空台。","竹榻无僧扫，松关有客来。","夕阳寒鸟集，凉露候虫哀。","祗苑犹如此，何方免劫灰。"]},{"t":"雨中桃花","f":"五言律诗","c":["霢霂过芳园，枝枝积泪痕。","色怜开处淡，香爱坠时闻。","采倦蜂须湿，衔多鸟咮芬。","东风解人意，吹片到衡门。"]},{"t":"萧芳桂挽诗四首 其一","f":"五言律诗","c":["芳桂殒清秋，无人不泪流。","通才今日少，遗恨几时休。","苔藓碑三尺，楸梧土一丘。","雁门前学士，地下与嬉游。"]},{"t":"萧芳桂挽诗四首 其二","f":"五言律诗","c":["卜宅泸江曲，逢迎意最真。","竹轩观奕倦，花屿放舟频。","莫究平生志，先捐未老身。","最怜黄壤魄，长梦绿窗人。"]},{"t":"萧芳桂挽诗四首 其三","f":"五言律诗","c":["豪杰空馀子，尊贤眼倍青。","挥金资客醉，辟馆教儿经。","天道幽难测，亲情痛不胜。","山阳怀旧笛，几度断肠听。"]},{"t":"萧芳桂挽诗四首 其四","f":"五言律诗","c":["有志惜无年，香名远近传。","客情千斛酒，岁计几庄田。","吐论常倾坐，收书不吝钱。","善祥钟令子，酷似乃翁贤。"]},{"t":"庚戌三月三日服阕之京舟次吉水","f":"五言律诗","c":["渐老怯离乡，那堪道路长。","病身愁北去，倦翮恋南翔。","旅梦缘钟断，忧怀藉酒忘。","低回愧江叟，白首钓鱼航。"]},{"t":"过清江","f":"五言律诗","c":["浦迥路迢迢，汀花带雨飘。","残灯江上庙，新水屋边桥。","鹭宿争投石，鸥惊或避桡。","无因谢轩冕，老作白云樵。"]},{"t":"次洪都","f":"五言律诗","c":["春波拍岸平，双桨一舟轻。","燕麦偏伤雨，莺花已负晴。","荒亭徐孺宅，遗堞灌婴城。","北去南来客，都缘利与名。"]},{"t":"舟过南京","f":"五言律诗","c":["钟阜白云边，桥陵锁暮烟。","圣谟真远矣，王气故依然。","玉帛诸番会，金汤万世传。","谁陈根本计，有力可回天。"]},{"t":"尉氏县","f":"五言律诗","c":["县舍邻溱洧，门当绿野开。","禽巢阶下树，蜗篆壁间苔。","俗质稀弦诵，田荒剩草莱。","宋金酣战处，武穆独奇才。"]},{"t":"宿兴国寺","f":"五言律诗","c":["人静钟初断，肩舆到寺门。","风檐寒犬吠，露井候虫喧。","弱蔓低垂树，枯蓬密覆垣。","蒲团分半席，暂憩给孤园。"]},{"t":"长葛道中","f":"五言律诗","c":["郊原殊苍莽，禾黍未全收。","桑柘千村晚，枌榆四野秋。","空林投倦鸟，枯草龁疲牛。","淡霭轻烟外，微茫见许州。"]},{"t":"晚至叶县","f":"五言律诗","c":["扰扰道途间，埃尘两鬓斑。","清风牛背笛，斜日马头山。","荷盖擎残绿，榴房破嫩殷。","蘋花秋水岸，空羡白鸥閒。"]},{"t":"王乔观","f":"五言律诗","c":["王子飞凫处，仙遥迹尚存。","城荒生暮霭，殿古锁秋云。","坏壁灯烟暗，閒阶草气薰。","古今为县者，神异独称君。"]},{"t":"留鲁山县","f":"五言律诗","c":["黎庶凋残甚，惟馀朴俭风。","名因元子重，地本鲁王封。","抚恤无贤令，流移有惰农。","谁将于蔿曲，歌向五云中。"]},{"t":"山中晓发","f":"五言律诗","c":["云气晓冥濛，人行万木中。","菊乾偏喜雨，柳弱自愁风。","绿鬓流年改，丹心往日同。","明时叨重寄，无补愧诸公。"]},{"t":"怀黄州滕太守","f":"五言律诗","c":["昔在南宫日，仙郎总俊髦。","分符荣出牧，载笔忆联曹。","身已朱幡贵，名犹粉署高。","公馀频吊古，舣棹访临皋。"]},{"t":"逢索员外话旧","f":"五言律诗","c":["相见仍青盻，相悲总白颠。","功名怜蹭蹬，患难喜生全。","小市三楹屋，荒村数亩田。","南交同宦者，若个在林泉。"]},{"t":"内乡县","f":"五言律诗","c":["岩邑千山里，荒村户半逃。","晓餐炊橡栗，寒火爇蓬蒿。","深秀非盘谷，凋零类石壕。","自伤无善政，抚问敢辞劳。"]},{"t":"新野即景","f":"五言律诗","c":["村暗濛濛雨，清流浅浅溪。","菊花长带湿，豆荚半沾泥。","野迥居民少，林昏去路迷。","自投新野界，蒿草与人齐。"]},{"t":"雨中赴唐县","f":"五言律诗","c":["冒雨趍唐县，蓬蒿已厌看。","长途泥滑滑，平地水漫漫。","枵腹流民馁，单衣稚子寒。","抚巡兼劳徕，衰病敢求安。"]},{"t":"宿泌阳县田舍","f":"五言律诗","c":["民家深树里，下马点灯时。","风雨关门早，衣裳拜客迟。","艰难逢歉岁，逼迫后租期。","说到伤心处，潸然泪满颐。"]},{"t":"过光州望马中丞墓","f":"五言律诗","c":["元运方全盛，公文擅大家。","谨严真有法，悃愊信无华。","故里祠堂废，荒阡墓碣斜。","欲羞蘋藻荐，不敢驻行车。"]},{"t":"怀元进士龚友孚","f":"五言律诗","c":["世运沧桑改，公名汗简留。","六军怜骇散，四海竟横流。","徒屈英雄策，空遗社稷忧。","浮光垂白叟，仍解说才猷。"]},{"t":"晚赴西平","f":"五言律诗","c":["晚涉西平境，荒郊望欲迷。","暝烟村远近，寒树冢高低。","驿路通淮甸，僧房隔汝溪。","柏亭何处是，极目草萋萋。"]},{"t":"王侍读汝嘉挽诗 其一","f":"五言律诗","c":["识面嗟诚晚，论交觉独深。","麟经三世业，蠹简一生心。","诸老怜将尽，孤怀痛不禁。","遗弦空自绝，无处觅知音。"]},{"t":"王侍读汝嘉挽诗 其二","f":"五言律诗","c":["阀阅衣冠盛，才名伯仲齐。","宫袍裁赐锦，御酒拆封泥。","屡握脩书笔，频分应制题。","只今文燄在，犹自烛云霓。"]},{"t":"王侍读汝嘉挽诗 其三","f":"五言律诗","c":["少日边庭戍，曾驰草檄名。","谈兵诸将屈，较艺众人惊。","已并青城誉，仍兼玉署荣。","九京那可作，恻怆起深情。"]},{"t":"王侍读汝嘉挽诗 其四","f":"五言律诗","c":["玉堂陪末议，荏苒七年馀。","夜漏秋同听，春潮晓共趍。","仲淹空有策，和靖却无书。","垂老交游尽，临风泪满裾。"]},{"t":"宿舞阳开元寺","f":"五言律诗","c":["驱车巡郡邑，夜夜宿僧房。","窗掩芭焦雨，钟敲薜荔霜。","一灯千虑集，孤枕五更长。","无补惟宜退，先茔有草堂。"]},{"t":"归自南阳","f":"五言律诗","c":["去日犹秋暑，归时已冷霜。","江山非故里，人物是他乡。","老态随年出，离愁共路长。","埃尘如见恋，到处扑衣裳。"]},{"t":"经息县","f":"五言律诗","c":["岁晏经新息，晨征念路遥。","轻冰方尽合，残雪未全消。","行客归心切，居民馁腹枵。","停车徒自感，只合返渔樵。"]},{"t":"除日早饭田家","f":"五言律诗","c":["田家无节序，除日亦寻常。","破釜初炊黍，空槽旋压浆。","瓮寒齑结凌，窗湿纸粘霜。","远役如堪免，长贫不敢伤。"]},{"t":"除夕宿汝宁僧舍闻停止夫役喜而有作","f":"五言律诗","c":["除夕留僧寺，焚香对老禅。","青灯伴今夜，黄历换明年。","宵旰忧诚切，疮痍痛暂蠲。","明晨呼万岁，顿首玉阶前。"]},{"t":"过殽陵关","f":"五言律诗","c":["春尽殽陵道，千山万木中。","水声泉聒聒，云气雨濛濛。","嫩草溪边石，幽禽树杪风。","抱关黄发吏，宁解识终童。"]},{"t":"永思堂三首 其一","f":"五言律诗","c":["一自双亲逝，孤怀每自伤。","恍疑闻謦欬，犹似见羹墙。","厚禄嗟何及，遗言敢暂忘。","番湖东去水，不似此情长。"]},{"t":"永思堂三首 其二","f":"五言律诗","c":["人子思亲意，悠悠镇不穷。","常时瞻画像，每日想音容。","幽显虽云异，精诚或可通。","哀悰真罔极，长系寸心中。"]}]};